(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-cfg-batch-merge"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-1\">一 · 一次把 2B 拼成一次前向的线上翻车</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-2\">二 · 它不解决什么：三个明确的“不”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-3\">三 · 数据流：从请求队列到 scheduler 的一圈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-4\">四 · 适用边界的量化判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-5\">五 · 失败模式的工程对策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-6\">六 · 边界之外：它和相邻算法的分工</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-7\">七 · 批合并救不了的那一类请求：显存峰值、切分错位与 s 的刚性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-8\">八 · 请求入口：embedding 构造与缓存写入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-9\">九 · 批拼装：2B 张量的构造与显存峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-10\">十 · 单次 DiT 前向：M 维饱满与 MMA 利用率</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-11\">十一 · 输出切分与引导组合：FP32 上的线性运算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-12\">十二 · 写回与 scheduler 更新：单份 latent 的闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-13\">十三 · 跨步复用与失败路径的定位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-14\">十四 · 批合并的失效边界：从 concat 到合并的逐步代价审计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-15\">十五 · 批合并的失效边界与显存账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-16\">十六 · 合并公式的逐项拆解与推导关键步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-17\">十七 · 从公式到可实现的伪代码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-18\">十八 · 公式的边界条件与数值稳定性推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-19\">十九 · 合并公式与缓存、调度的耦合推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-20\">二十 · 批合并的边界条件与失效路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-21\">二十一 · 请求形态与 2B 批的匹配关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-22\">二十二 · 并发与批大小的配方边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-23\">二十三 · 负载不对时的三类失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-24\">二十四 · 与量化、分块的联合配方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-25\">二十五 · 规模上限与配方判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-26\">二十六 · 负载配方：批合并只在“显存换调度”划算时成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-27\">二十七 · 硬件档位：按 2B 峰值显存反推卡型与并行度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-28\">二十八 · 并行拓扑：把 concat 维放在最不该被切的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-29\">二十九 · 量化方案：concat 张量同权重、合并留 FP32</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-30\">三十 · KV 与条件缓存策略：跨步复用文本 embedding，负向单独驻留</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-31\">三十一 · 调度参数：B 的动态上限、s 的分层预设与回退路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-32\">三十二 · 可复现的配置思路：从单样本基准到整机配方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-33\">三十三 · 部署配方的边界：2B 显存峰值、并行拓扑与量化叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-34\">三十四 · 显存峰值：2B 张量与激活翻倍的真实账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-35\">三十五 · 带宽：显存往返与权重流的双重压力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-36\">三十六 · 通信：张量并行下的 2B 切分与集合通信放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-37\">三十七 · 吞吐公式：大 batch 的 MMA 利用率与收益上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-38\">三十八 · 尾延迟：合并放大 batch 内的最长路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-39\">三十九 · 崩点排序与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-40\">四十 · 规模上去以后，先崩的是显存峰值而不是算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-41\">四十一 · 精度失败：从 FP32 组合点向外扩散的污染链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-42\">四十二 · OOM：峰值翻倍与回退路径的确定性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-43\">四十三 · 批抖动：2B 拼接下的批形不稳</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-44\">四十四 · 路由不均与尾延迟尖刺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-45\">四十五 · 监控面与回滚开关的最小集合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-46\">四十六 · 失败模式与相邻算法的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-47\">四十七 · 失败模式与诊断：从精度溢出到批抖动的现场排查</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-48\">四十八 · 决策轴：把选择压缩成三个可测维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-49\">四十九 · 决策表：五种形态的适用条件对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-50\">五十 · 吞吐判据：2B 与 B 的收益边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-51\">五十一 · 稳定性对照：错位与溢出的不同暴露面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-52\">五十二 · 组合与迁移：从单卡到并行拓扑的选择顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-53\">五十三 · 边界判定：批合并、串行双前向与 CFG 蒸馏的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-cfg-batch-merge-sec-54\">五十四 · 同族算法怎么选：批合并、串行双前向与 CFG 蒸馏的决策边界</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:505px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 504.9 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"422.9\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求到达后先跑一次文本编码器，缓存 prompt embedding 与负…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"422.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">每步把 [cond; uncond] 在 batch 维 cat 成 2B…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"422.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输出按前半/后半切片，做 x = x_u + s·(x_c − x_u) …</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"422.9\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">组合结果写回单份 latent，进入下一步 scheduler</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"422.9\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">文本 embedding 跨步复用，避免每步重算 T5/CLIP</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-cfg-batch-merge-sec-1\">一 · 一次把 2B 拼成一次前向的线上翻车</h3>\n<p>某在线文生图服务在 Blackwell 单卡上把 CFG 批合并（batch merge）上线，请求队列里 B=8 的并发，按 2B=16 组织送入 DiT。上线首日流量平稳时吞吐确实上去了，但当晚高峰出现一批 1024×1024、长 prompt 的请求，concat 后的 2B 激活张量把显存峰值顶到预算之外，进程直接 OOM。服务端的降级策略是回退到串行双前向——也就是每步先跑条件、再跑无条件——结果单请求时延抬升，队列积压，SLO 被打穿。这次事故的根因不是算法错，而是把“批合并”当成了无条件加速开关：它换来的吞吐是以显存峰值为抵押的，而这个抵押在高分辨率、大 DiT、长 prompt 三者叠加时会立刻到期。</p>\n<p>Classifier-Free Guidance 的原始形态要求每步跑两次前向：一次带条件 prompt，一次带空 prompt（负向），然后在输出端做线性外推。两次前向的 KV、激活、kernel launch 全部独立，服务端 batch 被 CFG 撕裂成两半，GEMM 的 M 维只有 B 而不是 2B，Tensor Core 利用率低，调度开销翻倍。批合并要解决的就是这个“结构性撕裂”：把条件与无条件样本在 batch 维拼成一次前向，让 2B 的 M 维把 MMA 喂饱，同时让文本编码只算一次。公式上输出端的合并是：</p>\n<div class=\"formula\">$$\\epsilon = \\epsilon_{\\mathrm{uncond}} + s\\,(\\epsilon_{\\mathrm{cond}} - \\epsilon_{\\mathrm{uncond}})$$</div>\n<p>其中 $\\epsilon_{\\mathrm{uncond}}$ 是前半批空 prompt 的 noise 预测，$\\epsilon_{\\mathrm{cond}}$ 是后半批条件 prompt 的预测，$s$ 为 guidance scale。合并结果写回单份 latent，交给 scheduler 更新，下一步再 concat。吞吐的对比可以写成 $\\text{Throughput}\\approx\\frac{2B}{t_{\\text{fwd}}(2B)}$ 对 $\\frac{B}{t_{\\text{fwd}}(B)}$：只要 $t_{\\text{fwd}}(2B)$ 明显小于 $2\\,t_{\\text{fwd}}(B)$，合并就赚；Blackwell 上大 batch 的 MMA 利用率更高，实测吞吐提升 1.3–1.6 倍，文本编码只算一次还能在长 prompt 场景省下可观的 prefill 开销。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-2\">二 · 它不解决什么：三个明确的“不”</h3>\n<p>第一，批合并不改模型结构，也不减少单步的算术总量。它把两次小前向拼成一次大前向，减少的是 kernel launch、调度碎片和文本编码的重复，而不是把 2B 的计算量压成 B。所以它和 CFG 蒸馏（把 guidance 蒸进单分支、真正只跑一次 B）是两条路：蒸馏省算力但有训练成本、改模型；批合并无训练成本、不改结构，代价是显存峰值翻倍。第二，它不解决显存紧张场景。concat 后 2B 张量的激活显存翻倍，高分辨率大 DiT 下直接触发 OOM，这时需要的是分块、offload 或量化把峰值压回预算，而不是继续加大 batch。第三，它不提供按样本动态调 $s$ 的能力：合并发生在输出端，一次前向里所有样本共享同一个 guidance scale，长尾请求与批量请求共用同一 $s$ 时，画质与语义对齐难以兼顾，只能在请求入口按业务分层预设。</p>\n<p>换句话说，批合并是一个“调度层”的优化，不是“算术层”的优化，也不是“显存层”的优化。它把 CFG 的两路前向在时间轴上对齐，换来更饱满的 GEMM 和更少的 launch，但它把显存峰值和 $s$ 的灵活性作为交换条件摆上桌面。工程判断的第一条就是：先确认显存预算能否容纳 2B 峰值，再谈吞吐收益。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-3\">三 · 数据流：从请求队列到 scheduler 的一圈</h3>\n<p>按数据流顺序走一遍。请求到达后先跑一次文本编码器（T5/CLIP），缓存 prompt embedding 与负向 embedding，这两份 embedding 跨步复用，避免每步重算。每步开始时，把条件 latent 与无条件 latent 在 batch 维 cat 成 2B 输入张量送入 DiT；DiT 单次前向产出 2B 的 noise 预测，按前半/后半切片；输出端按 guidance scale 线性组合合并为 B，写回单份 latent，进入 scheduler 更新，下一 step 重复 concat。伪代码思路是：</p>\n<ul>\n<li>emb_c, emb_u = encode(prompt), encode(empty)  // 只算一次，缓存</li>\n<li>for step in scheduler: x2 = cat([x_u, x_c], dim=0)  // 固定前半 uncond、后半 cond</li>\n<li>eps2 = dit(x2, cat([emb_u, emb_c]))  // 一次 2B 前向</li>\n<li>eps_u, eps_c = split(eps2, B)  // 切分索引与 concat 顺序一一对应</li>\n<li>eps = eps_u + s * (eps_c - eps_u)  // 在 FP32 中组合</li>\n<li>x = scheduler_step(x, eps)  // 单份 latent 回到下一步</li>\n</ul>\n<p>这个圈里有两个代价点必须盯住。其一是显存：2B 激活翻倍，高分辨率下可能 OOM，需要与量化/分块配合，把峰值压回预算。其二是数值：引导尺度 $s$ 大时动态范围变大，低精度下易溢出，组合必须保持在 FP32，不能把 $s\\,(\\epsilon_{\\mathrm{cond}}-\\epsilon_{\\mathrm{uncond}})$ 丢进 FP8 里算。concat 顺序也必须固定为前半 uncond、后半 cond，切分索引与合并公式一一对应，否则 guidance 方向反转，输出画面过饱和或语义偏离 prompt，而且这种错位很难从日志里定位——它不报错，只是画质悄悄变坏。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-4\">四 · 适用边界的量化判断</h3>\n<p>把适用边界写成可判定的条件，而不是模糊的“看情况”。适合批合并的场景同时满足三条：显存充裕到能容纳 2B 峰值（含激活与 KV）、batch 可稳定拼到 2B、DiT 规模中等且分辨率不顶格。不适合的场景也清晰：高分辨率大 DiT 下峰值翻倍易 OOM，需先分块或 offload；业务需要按请求动态调 $s$（例如不同客户不同引导强度）；以及单请求时延优先、并发很低的场景——此时 2B 拼不满，合并的调度收益被显存代价抵消。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>串行双前向</th><th>批合并 2B</th></tr></thead><tbody>\n<tr><td>每步 kernel launch</td><td>两次</td><td>一次，调度开销减半</td></tr>\n<tr><td>GEMM 的 M 维</td><td>B，偏瘦</td><td>2B，Tensor Core 更饱满</td></tr>\n<tr><td>激活显存峰值</td><td>约 B 量级</td><td>约 2B 量级，翻倍</td></tr>\n<tr><td>文本编码</td><td>每路各算或重复</td><td>只算一次并缓存</td></tr>\n<tr><td>$s$ 灵活性</td><td>可按样本调</td><td>输出端固定，需入口分层预设</td></tr>\n</tbody></table>\n<p>规模上限由单卡显存峰值与并行拓扑决定：张量并行能把单卡峰值摊薄，但 2B 的 concat 仍然发生在每张卡的本地 batch 上，拓扑不改变“峰值翻倍”这个事实，只改变每卡分到多少。所以扩容不是解法，压峰值才是。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-5\">五 · 失败模式的工程对策</h3>\n<p>三类失败模式各有对策。OOM 类：在请求入口按分辨率与 DiT 规模做准入控制，把 B 的上界设为显存预算除以单样本 2B 峰值，超限请求走串行双前向或降分辨率，而不是让进程崩掉再回退。错位类：把 concat 顺序与切分索引写进同一个常量或同一个函数，禁止在两处分别硬编码；上线前用固定 seed 与固定 prompt 做一次方向校验，确认 $s$ 增大时输出朝条件方向偏移。$s$ 僵化类：在请求入口按业务分层预设 $s$，把长尾请求与批量请求分流到不同队列，避免同一 $s$ 硬套所有请求。</p>\n<p>还有一条与量化叠加的注意：concat 后的 2B 张量按同一权重计算，量化（FP8/FP4）可以叠加，但输出端的引导组合必须留在 FP32，因为 $s$ 大时 $\\epsilon_{\\mathrm{cond}}-\\epsilon_{\\mathrm{uncond}}$ 的差值动态范围会放大，低精度下先溢出再合并，画质损伤不可逆。这与 DiT NVFP4 混合精度那部分讲的精度分层是同一套判断：算术可以低精度，组合不能。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-6\">六 · 边界之外：它和相邻算法的分工</h3>\n<p>批合并与 CFG 蒸馏的分工是“省显存换灵活性”对“省算力换训练成本”。与特征缓存、块级跳步那类跨步复用算法也不同：后者省的是跨 step 的重复计算，批合并省的是同一步内的两路撕裂，两者可以叠加——缓存把某些 step 的 DiT 前向整个跳过，批合并把没跳过的 step 拼成 2B。与阶段级扩散服务流水的关系是：流水线把预填/解码或不同阶段拆到不同资源池，批合并发生在单个 DiT 阶段内部，是阶段内的批组织方式，不是阶段间的调度。</p>\n<p>最终落在一个工程判断上：批合并的收益上限由 $t_{\\text{fwd}}(2B)$ 与 $2\\,t_{\\text{fwd}}(B)$ 的比值决定，而这个比值在 Blackwell 上取决于 M 维是否被喂饱、kernel launch 是否成为瓶颈；它的成本下限由显存峰值决定，而这个峰值在高分辨率大 DiT 下会直接变成 OOM。所以正确的上线顺序是先用分块、offload 或量化把 2B 峰值压进预算，再打开批合并，而不是反过来先开合并再救火——那次线上事故就是把顺序做反了。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-7\">七 · 批合并救不了的那一类请求：显存峰值、切分错位与 s 的刚性</h3>\n\n<p>先把事故讲清楚，因为它决定了这个方案该不该上。某在线文生图服务把 CFG 批合并接进主链路后，白天低峰一切正常，晚高峰高分辨率档位开始零星 500。根因不在合并逻辑本身，而在 concat 之后的 2B 张量：原本 B 已经贴着显存预算跑，翻倍后激活峰值直接顶穿，调度器被迫把该档位回退成串行双前向，于是同一张卡上出现了两种执行路径——合并路径的 2B 大 GEMM 与回退路径的两次 B 小 GEMM 争抢 SM，尾延迟被拉长，SLO 从单请求时延维度崩掉。这类事故的教训是：批合并把“每步两次前向”的算力问题换成了“显存峰值翻倍”的容量问题，它不消灭代价，只搬运代价。公式上收益来自 $$\\text{Throughput}\\approx\\frac{2B}{t_{\\text{fwd}}(2B)}\\ \\text{vs}\\ \\frac{B}{t_{\\text{fwd}}(B)}$$，即大 batch 的 MMA 利用率更高、kernel launch 与调度开销减半；但代价项是激活显存随 2B 线性上升，高分辨率大 DiT 下这一项往往先于算力成为约束。</p>\n\n<p>由此划出第一条边界：<strong>它解决的是“算力与调度被 CFG 撕裂”，不解决“显存不够”</strong>。合并后 concat 的 2B 张量按同一权重计算，量化可与 FP8/FP4 叠加来压权重与部分激活，但激活峰值本身仍需分块或 offload 才能压回预算。工程判断很直接：先算单卡显存在目标分辨率、目标 DiT 规模下的峰值，若 2B 已经越界，就不要指望合并路径兜底，而应把 B 调小到 2B 落回预算内，或者干脆留在串行双前向。规模上限由单卡显存峰值与并行拓扑共同决定，张量并行能把单卡峰值摊薄，但通信开销会吃掉一部分合并带来的 GEMM 收益，这个账要在容量规划阶段算，而不是上线后靠回退补。</p>\n\n<p>第二条边界是正确性上的脆弱点：concat 顺序必须固定为前半 uncond、后半 cond，切分索引与合并公式 $$\\epsilon = \\epsilon_{\\mathrm{uncond}} + s\\,(\\epsilon_{\\mathrm{cond}} - \\epsilon_{\\mathrm{uncond}})$$ 必须一一对应。一旦顺序写反或切片偏移，guidance 方向反转，输出表现为过饱和或语义偏离 prompt，而日志里只有正常的时延与显存曲线，几乎无法定位。这是纯工程约束：把 concat 与 slice 封装成同一个函数、用命名而非位置索引来取两半，比事后加监控更省事。同理，引导组合必须留在 FP32——s 较大时数值动态范围变大，低精度下组合环节易溢出，把这一步降精度换吞吐是得不偿失的。</p>\n\n<p>第三条边界关乎产品灵活性：合并发生在输出端，意味着 <em>s</em> 无法在中途按样本动态调整。长尾请求与批量请求共用同一 <em>s</em> 时，画质与语义对齐难以兼顾，只能在请求入口按业务分层预设。这正是它与 CFG 蒸馏的分野——蒸馏把 guidance 蒸进单分支，不改显存峰值却要训练成本；批合并不动模型结构、零训练成本，代价是显存翻倍与 <em>s</em> 的刚性。适用面因此收窄：显存充裕、B 能拼到 2B、DiT 规模中等的在线服务是它的主场；高分辨率大 DiT、需要逐请求调 <em>s</em> 的场景，它只能作为可选路径而非默认路径。</p>\n\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价</th><th>工程处置</th></tr></thead><tbody><tr><td>2B 激活越界</td><td>OOM、回退串行、尾延迟上升</td><td>降 B、分块/offload、张量并行摊薄</td></tr><tr><td>concat 顺序或切片错位</td><td>guidance 反转、画质异常且难定位</td><td>封装 concat+slice、命名索引</td></tr><tr><td>s 固定于输出端</td><td>长尾与批量共用 s，对齐受损</td><td>入口按业务分层预设 s</td></tr></tbody></table>\n<h3 id=\"alg-cfg-batch-merge-sec-8\">八 · 请求入口：embedding 构造与缓存写入</h3>\n<p>批合并的第一步发生在 DiT 之前，却决定了后面所有步骤的代价结构。请求从队列取出时，调度器拿到的是 prompt 文本、负向 prompt（或空串）、guidance scale <em>s</em>、分辨率与步数。此处的输入是原始文本，输出是两份已经落到显存里的 embedding 张量：一份条件 embedding <code>e_c</code>，形状为 [B, L, D]，一份无条件 embedding <code>e_u</code>，形状相同。关键在于这两份 embedding 只算一次，之后跨全部采样步复用，因此文本编码器（T5/CLIP 一类）的 prefill 开销被摊薄到 N 步上，单步摊销为 <code>t_text / N</code>。对长 prompt 场景，这个摊销项不可忽略：文本编码器本身也是 Transformer 前向，序列长时其算力与显存带宽开销接近一次小 batch 的 DiT 步。</p>\n<p>缓存写入的工程细节在于布局。为了让后续 concat 成为零拷贝或单次拷贝，两份 embedding 应在同一块连续显存上按前半/后半排布，即 <code>[e_u; e_c]</code> 的物理顺序与逻辑顺序一致。若框架默认把 cond 放前、uncond 放后，则必须在入口处显式交换，否则后面切分索引与合并公式错位，guidance 方向反转——这是本机制最隐蔽的失败模式，输出表现为画面过饱和或语义偏离 prompt，而日志里一切正常。此步的代价是显存：两份 embedding 常驻，占用量为 <code>2·B·L·D·dtype_bytes</code>，在 FP16 下对 B=8、L=77、D=2048 的量级是数 MB 级，相对 DiT 激活可忽略，但它必须与 KV 缓存一起被计入常驻预算。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-9\">九 · 批拼装：2B 张量的构造与显存峰值</h3>\n<p>每个采样步开始时，调度器把当前 latent 复制成两份，沿 batch 维拼成 2B：前半是 uncond 分支的 latent <code>x_u</code>，后半是 cond 分支的 <code>x_c</code>。初始步两份 latent 相同（同一噪声种子），后续步因引导组合而分叉，因此复制不可省略。输入是 B 份 latent 与缓存的 embedding，输出是一个 [2B, C, H, W] 的输入张量与一个 [2B, L, D] 的 embedding 张量。这一步的代价是显存带宽：一次 2B 规模的写入加一次读取，在 H100 级别卡上是百微秒量级，但在 Blackwell 上由于 HBM3e 带宽更高，相对 DiT 前向的占比下降，这正是批合并在大卡上更划算的原因之一。</p>\n<p>显存峰值在此刻翻倍，这是本机制的核心代价。激活显存从 <code>M_act(B)</code> 变为 <code>M_act(2B)</code>，而 DiT 的激活随分辨率平方增长，高分辨率大模型下 <code>M_act(2B)</code> 可能直接越过单卡预算，触发 OOM，服务端被迫回退到串行双前向，吞吐跌回原点。工程上的压回手段是与分块、offload 或低精度激活配合：把 2B 张量按空间块切分送入 DiT，或在层间把部分激活换出到主机内存。判断是否值得合并，取决于 <code>M_act(2B) + M_weights + M_kv</code> 是否仍在预算内，若余量不足则合并的收益被回退风险抵消。</p>\n<div class=\"formula\">$$\\text{Peak}\\approx M_{\\text{weights}}+M_{\\text{act}}(2B)+M_{\\text{emb}}(2B)+M_{\\text{kv}}$$</div>\n\n<h3 id=\"alg-cfg-batch-merge-sec-10\">十 · 单次 DiT 前向：M 维饱满与 MMA 利用率</h3>\n<p>2B 张量送入 DiT 后，整个去噪网络只跑一次。输入是拼装好的 latent 与 embedding，输出是 [2B, C, H, W] 的 noise 预测。此步的收益来自 GEMM 的 M 维：串行双前向时每次 GEMM 的 M=B，两次 launch 各自受限于较小的 M，Tensor Core 的利用率被 tile 边界吃掉一部分；合并后 M=2B，tile 划分更饱满，kernel launch 次数减半，调度开销与显存往返同步减半。Blackwell 的 tcgen05 与 2-SM MMA 对大 M 更友好，TMEM 的驻留能力让权重与激活的复用率提升，因此合并带来的吞吐增益在 Blackwell 上比在上一代更明显，实测区间为 1.3–1.6 倍。</p>\n<p>用公式表达这个收益：串行时吞吐约为 <code>B / t_fwd(B)</code>，合并后约为 <code>2B / t_fwd(2B)</code>，比值即 <code>2·t_fwd(B) / t_fwd(2B)</code>。若 <code>t_fwd</code> 对 batch 近似线性，比值趋近 1，收益只来自 launch 开销；若 <code>t_fwd(2B) &lt; 2·t_fwd(B)</code>，即大 batch 摊薄了固定开销与权重读取，比值大于 1。这就是为什么合并的收益随 DiT 规模与卡型变化：权重读取在单步中占固定成本，B 越小，这部分占比越高，合并的边际收益越大。代价方面，2B 前向的功耗与算力占用是单次的，但总能耗与串行两次相近，合并省下的是调度与带宽，不是 FLOPs。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-11\">十一 · 输出切分与引导组合：FP32 上的线性运算</h3>\n<p>前向产出 2B 的 noise 预测后，输出端按固定索引切成两半：前半 <code>ε_u</code> 对应空 prompt，后半 <code>ε_c</code> 对应条件 prompt。切分索引必须与入口处的 concat 顺序严格一致，这是全流程唯一的硬约束。随后做引导组合，输入是两个 [B, C, H, W] 张量，输出是一个 [B, C, H, W] 的合并结果：</p>\n<div class=\"formula\">$$\\epsilon=\\epsilon_{\\mathrm{uncond}}+s\\,(\\epsilon_{\\mathrm{cond}}-\\epsilon_{\\mathrm{uncond}})$$</div>\n<p>此步的代价是数值稳定性。当 <em>s</em> 较大时，<code>ε_c − ε_u</code> 的差值被放大，动态范围扩张，若在 FP16 或 BF16 上做组合，差值项容易溢出或损失精度，表现为高对比区域的伪影。工程做法是把组合运算提升到 FP32：切片后先转 FP32，算完再转回 latent 的 dtype 送入 scheduler。这一步的显存代价是临时的 FP32 缓冲，大小为 <code>B·C·H·W·4</code> 字节，对高分辨率是数十 MB 级，必须计入峰值预算；带宽代价是两次 dtype 转换的读写。若与 FP8/FP4 量化叠加，组合必须在量化之外单独保留 FP32 路径，不能把引导运算塞进低精度 kernel。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-12\">十二 · 写回与 scheduler 更新：单份 latent 的闭环</h3>\n<p>组合结果写回单份 latent，batch 维从 2B 收缩回 B，进入 scheduler 做一步更新（DDIM、Euler 或整流流采样器的更新式）。输入是合并后的 <code>ε</code> 与当前 latent，输出是下一步的 latent <code>x_{t+1}</code>。此步的代价是显存往返：一次 B 规模的写入，以及下一步开始时再次复制成 2B 的读取。整个闭环的显存流量为每步 <code>2B</code> 写 + <code>2B</code> 读 + <code>B</code> 写，相比串行双前向的两次独立读写，合并后在总量上并未减少，减少的是 kernel 数量与同步点。scheduler 更新本身是逐元素的轻量运算，在 Blackwell 上由 CUDA core 承担，与 Tensor Core 的 GEMM 形成互补，不构成瓶颈。</p>\n<p>闭环的稳定性还取决于 <em>s</em> 的固定性。引导组合发生在输出端，意味着 <em>s</em> 在整个采样过程中对同一请求是常量，无法在中途按样本动态调整。若业务需要按请求分层设定 <em>s</em>（例如长尾请求用低 <em>s</em> 保语义、批量请求用高 <em>s</em> 保画质），必须在请求入口处预设，并让同一 batch 内的请求共享同一 <em>s</em>，否则合并公式的标量无法逐样本广播。这是批合并相对串行双前向的灵活性损失，工程上通过 batch 分组来缓解：按 <em>s</em> 分桶，同桶内合并，桶间串行。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-13\">十三 · 跨步复用与失败路径的定位</h3>\n<p>文本 embedding 跨步复用是本机制中唯一真正“省下来”的部分：N 步采样中，文本编码器只跑一次，省下的 prefill 算力为 <code>(N−1)·t_text</code>。KV 缓存同理，若 DiT 使用交叉注意力，条件侧的 KV 只算一次并在步间复用，KV 显存为 <code>2·B·L·d_head·layers</code> 量级，与 latent 激活分开计账。此处的工程判断是：embedding 与 KV 的缓存命中率决定了合并的实际收益，若请求频繁变更 prompt，缓存失效，摊销归零，合并只剩下 batch 维的收益。</p>\n<p>失败路径的定位依赖两个锚点。其一是 concat 顺序：入口处的物理排布、切分索引、合并公式三者必须一一对应，任何一处交换都会让 guidance 方向反转，输出异常但无报错，排查时应先打印切片后的均值与方差，确认 <code>ε_c</code> 与 <code>ε_u</code> 的统计差异符合预期。其二是显存峰值：OOM 发生时，先看 <code>M_act(2B)</code> 是否越过预算，再决定是降 B、上分块还是回退串行。这两个锚点覆盖了本机制绝大多数线上故障，其余问题多落在量化与组合精度的交互上，需单独在 FP32 路径上做数值对照。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-14\">十四 · 批合并的失效边界：从 concat 到合并的逐步代价审计</h3>\n<p>把 CFG 两路前向拼成一次 2B 前向，收益来自 GEMM 的 M 维饱满与 kernel launch 减半，但每一步的代价并不对称。按数据流拆开看：请求出队后先跑文本编码器，产出条件 embedding 与空 prompt 的负向 embedding 并缓存，这一步是纯 prefill，长 prompt 下 T5/CLIP 的算力开销一次性付清，跨步复用后不再重复；随后每步把两路 latent 在 batch 维 cat 成 2B 张量送入 DiT，单次前向产出 2B 的 noise 预测，按前半 uncond、后半 cond 切分，在输出端做 $\\epsilon=\\epsilon_{\\mathrm{uncond}}+s(\\epsilon_{\\mathrm{cond}}-\\epsilon_{\\mathrm{uncond}})$ 的线性组合，写回单份 latent 交给 scheduler。关键代价集中在第二、三步：激活显存随 batch 翻倍，而组合必须落在 FP32 才能容纳 $s$ 放大后的动态范围，这两项叠加才是峰值显存的真实来源，而非权重本身。</p>\n<p>吞吐账要用公式核对，不能只看“合并成一次前向”这句话。$$\\text{Throughput}\\approx\\frac{2B}{t_{\\text{fwd}}(2B)}\\ \\text{vs}\\ \\frac{B}{t_{\\text{fwd}}(B)}$$ 只有当 $t_{\\text{fwd}}(2B)&lt;2\\,t_{\\text{fwd}}(B)$ 时批合并才净赚，这依赖 2B 规模下 Tensor Core 利用率高于两次小 batch GEMM；一旦 2B 越过显存预算被迫缩小 B，或触发分块与 offload 引入额外搬运，$t_{\\text{fwd}}(2B)$ 的相对优势就被吃掉。Blackwell 上大 batch 的 MMA 利用率更高是收益来源，但收益上限由单卡显存峰值与并行拓扑共同锁定，规模不能无限外推。</p>\n<p>失效条件有三类，且都难以从日志直接定位。其一是显存：高分辨率、大 DiT 下 concat 后的 2B 张量使峰值翻倍，未配合分块或 offload 即触发 OOM，服务端 batch 只能回退串行双前向，吞吐回落且调度路径分叉。其二是索引错位：concat 顺序必须固定为前半 uncond、后半 cond，切分索引与合并公式一一对应，顺序颠倒等价于 guidance 方向反转，输出过饱和或语义偏离 prompt，表现为画质异常而非报错。其三是灵活性：$s$ 固定在输出端合并，中途无法按样本动态调整，长尾请求与批量请求共用同一 $s$ 时画质与语义对齐难以兼顾，只能在请求入口按业务分层预设。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入→输出</th><th>主要代价</th><th>失效点</th></tr></thead><tbody><tr><td>文本编码</td><td>prompt→cond/uncond embedding</td><td>一次性 prefill，跨步复用</td><td>长 prompt 下编码器占用显存</td></tr><tr><td>concat 前向</td><td>2B latent→2B noise</td><td>激活显存翻倍、GEMM M 维饱满</td><td>高分辨率 OOM</td></tr><tr><td>引导组合</td><td>2B→B latent</td><td>FP32 组合、额外读写往返</td><td>顺序错位致方向反转</td></tr><tr><td>scheduler</td><td>B latent→下一步输入</td><td>单份 latent 更新</td><td>$s$ 不可按样本动态调</td></tr></tbody></table>\n<p>与 CFG 蒸馏相比，批合并不改模型结构、无训练成本，代价是显存峰值翻倍与 $s$ 灵活性下降；与串行双前向相比，它把两次 kernel launch 与两次小 batch GEMM 压成一次，调度开销减半。工程判断应落在“2B 是否装得下”这一条硬约束上：先按目标分辨率与 DiT 规模测算激活峰值，再决定 B 的上限，把量化（FP8/FP4 按同一权重计算 concat 后的 2B 张量）与分块作为兜底，而不是默认批合并总是划算。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-15\">十五 · 批合并的失效边界与显存账</h3>\n<p>批合并把两次前向压成一次，代价立刻体现在激活峰值上：concat 后的 2B 张量按同一份权重计算，中间激活、attention workspace、TMEM 占用全部按 2B 规模分配，显存峰值近似翻倍。设单样本激活为 $A$、权重为 $W$、KV/文本缓存为 $C$，则合并前后峰值之比约为 $(2A+W+C)/(A+W+C)$，当 $A$ 远大于 $W$ 时该比值趋近 2。高分辨率、大 DiT 档位下这一步最容易踩线：未配合分块或 offload 时直接 OOM，调度器只能回退串行双前向，吞吐瞬间掉回原点。工程上的可行做法是把 B 压到显存预算允许的上限，再用分块 attention 或激活 offload 把峰值拉回预算内，而不是盲目把 batch 拼大。</p>\n<p>第二个失效点是索引契约。concat 顺序必须固定为前半 uncond、后半 cond，切分索引与 $\\epsilon=\\epsilon_{\\mathrm{uncond}}+s(\\epsilon_{\\mathrm{cond}}-\\epsilon_{\\mathrm{uncond}})$ 一一对应；一旦顺序反转或切片偏移一位，guidance 方向整体反向，输出表现为过饱和或语义偏离 prompt，而日志里只有正常的时延与显存曲线，定位成本极高。因此合并逻辑应作为独立算子单元测试，用固定随机种子比对串行双前向的输出，把“方向正确”变成可回归的断言，而不是靠肉眼审图。</p>\n<p>第三个边界是灵活性。引导组合发生在输出端，$s$ 在整批内是常量，无法按样本动态调整；长尾请求与批量请求共用同一 $s$ 时，画质与语义对齐难以兼顾。解决办法是在请求入口按业务分层预设 $s$ 并分组入批，把动态性从 step 级降到请求级。与 CFG 蒸馏相比，批合并不改模型结构、无训练成本，但显存代价更高、$s$ 更僵硬；它适合显存充裕、DiT 规模中等、$s$ 可按业务分层的在线服务，规模上限由单卡显存峰值与并行拓扑共同决定。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价</th><th>缓解手段</th></tr></thead><tbody><tr><td>高分辨率大 DiT，2B 激活峰值翻倍</td><td>OOM，回退串行双前向，吞吐腰斩</td><td>压 B、分块 attention、激活 offload</td></tr><tr><td>concat 顺序/切分索引错位</td><td>guidance 反向，画质劣化且难定位</td><td>固定顺序 + 与串行结果做回归比对</td></tr><tr><td>$s$ 固定在输出端</td><td>长尾与批量请求画质难兼顾</td><td>请求入口按业务分层预设 $s$ 并分组</td></tr></tbody></table>\n<h3 id=\"alg-cfg-batch-merge-sec-16\">十六 · 合并公式的逐项拆解与推导关键步</h3>\n<p>批合并的核心不在“把两路拼起来”这个动作本身，而在于拼接后的 2B 张量经过 DiT 前向后，如何在输出端精确还原成一次引导。写成统一形式：</p>\n<div class=\"formula\">$$\\hat{x}=x_{\\text{uncond}}+s\\,(x_{\\text{cond}}-x_{\\text{uncond}})$$</div>\n<p>四项各有明确所指。<em>x</em><sub>uncond</sub> 是前半批（空 prompt / 负向 embedding）的模型输出，它承担“无条件先验”的角色，决定画面的基础分布；<em>x</em><sub>cond</sub> 是后半批（真实 prompt）的输出，携带语义对齐的方向；两者之差 <em>x</em><sub>cond</sub>−<em>x</em><sub>uncond</sub> 是引导向量，即“条件相对无条件把预测往哪个方向推”；<em>s</em> 是这个方向的放大系数。注意公式作用在模型原始输出（noise 预测 ε 或 velocity v）上，而不是作用在 latent 上——这一点决定了合并必须发生在 scheduler 更新之前、DiT 输出之后。</p>\n<p>推导的关键一步是把“两次独立前向”写成“一次批量前向”的等价变换。设单样本前向为 <em>f</em>(<em>x</em>, <em>c</em>; θ)，串行 CFG 每步计算 <em>f</em>(<em>x</em>, ∅) 与 <em>f</em>(<em>x</em>, <em>c</em>)。由于 DiT 在 batch 维上对样本彼此独立（注意力不跨样本、归一化按样本统计），把两路 latent 沿 batch 维 cat 得到 <em>X</em>=[<em>x</em>;<em>x</em>]∈ℝ<sup>2B×…</sup>，配对的 condition 张量同样 cat，则：</p>\n<div class=\"formula\">$$f\\big([x;x],[\\varnothing;c];\\theta\\big)=\\big[f(x,\\varnothing;\\theta);\\ f(x,c;\\theta)\\big]$$</div>\n<p>这是整个算法成立的数学前提：批量前向的输出严格等于逐样本前向的拼接，误差仅来自 GEMM 分块与归约顺序的浮点非结合性，量级在低精度下需用 FP32 累加压住。有了这个等式，输出端切片 <code>out[:B]</code> 与 <code>out[B:]</code> 就分别对应两项，合并只是逐元素线性组合，代价可忽略。反过来，若模型含跨样本耦合（如 batch 级统计归一化或跨样本注意力），等式失效，合并结果与串行结果不再等价——这是选用该算法前必须确认的结构约束。</p>\n<p>系统代价落在三处。其一，算力：合并把两次 <em>t</em><sub>fwd</sub>(B) 变成一次 <em>t</em><sub>fwd</sub>(2B)，吞吐对比为</p>\n<div class=\"formula\">$$\\text{Throughput}\\approx\\frac{2B}{t_{\\text{fwd}}(2B)}\\ \\text{vs}\\ \\frac{B}{t_{\\text{fwd}}(B)}$$</div>\n<p>只要 <em>t</em><sub>fwd</sub>(2B)&lt;2·<em>t</em><sub>fwd</sub>(B)，合并即净赚；Blackwell 上 2B 的 M 维让 tcgen05 MMA 的 tile 填充更满、kernel launch 与调度开销减半，实测吞吐提升 1.3–1.6 倍。其二，显存：激活与中间张量随 batch 翻倍，高分辨率大 DiT 下峰值直接翻倍，是 OOM 的主因。其三，数值：<em>s</em> 较大时 <em>x</em><sub>cond</sub>−<em>x</em><sub>uncond</sub> 的动态范围被放大，低精度下组合易溢出，故合并必须在 FP32 完成后再降回计算精度。</p>\n<p>具体例子：在线文生图服务，B=8 的请求批，串行 CFG 每步两次 8 样本前向、两次 kernel launch；合并后一次 16 样本前向，launch 减半，M 维从 8 抬到 16，Tensor Core 占用更实。若单步 <em>t</em><sub>fwd</sub>(16)&lt;2<em>t</em><sub>fwd</sub>(8)，则单步时延下降、单位时间出图数上升；代价是激活峰值约翻倍，需在显存预算内选 B。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-17\">十七 · 从公式到可实现的伪代码</h3>\n<p>把上面的等式落成代码，关键是三件事：拼接顺序固定、切片索引与公式一一对应、文本侧只算一次。伪代码按数据流给出：</p>\n<ul>\n<li><strong>入口预计算</strong>：对每个请求跑一次文本编码器，得到 <code>emb_c</code>（条件）与 <code>emb_u</code>（空/负向），连同负向模板一起写入条件缓存，按 prompt 哈希索引，跨步、跨请求复用。</li>\n<li><strong>每步组装</strong>：取 B 个在途请求，构造 <code>X = cat([x_u_list, x_c_list], dim=0)</code>，长度 2B；condition 张量同序 cat，前半为 <code>emb_u</code>、后半为 <code>emb_c</code>。</li>\n<li><strong>单次前向</strong>：<code>out = dit(X, cond, t)</code>，输出形状 2B；不做任何中途切片。</li>\n<li><strong>切片与合并</strong>：<code>e_u = out[:B]</code>，<code>e_c = out[B:]</code>，在 FP32 下算 <code>e = e_u + s*(e_c - e_u)</code>，再 cast 回 latent dtype。</li>\n<li><strong>调度更新</strong>：<code>x = scheduler_step(x, e, t)</code>，只保留 B 份 latent 进入下一步；2B 的中间激活即时释放。</li>\n</ul>\n<p>伪代码层面的两个易错点必须写死。第一，<strong>顺序契约</strong>：concat 的前半必须是 uncond、后半必须是 cond，切片 <code>[:B]</code>/<code>[B:]</code> 与公式的 <em>x</em><sub>uncond</sub>/<em>x</em><sub>cond</sub> 严格对应；一旦顺序或索引错位，引导方向反转，输出过饱和或语义偏离 prompt，且日志里看不出异常——建议在组装处加断言校验 condition 张量的 tag 序列。第二，<strong>合并精度</strong>：即使 DiT 以 FP8/FP4 计算，<code>e_c - e_u</code> 与 <code>s*</code> 乘法也要在 FP32 做，否则大 <em>s</em> 下差值溢出会污染整步。</p>\n<p>系统代价体现在调度层：合并后每步只有一次前向，kernel launch 与 host 侧调度开销减半，但 2B 的激活峰值把显存预算吃紧。工程上常配合分块 DiT 或 activation offload 把峰值压回预算，代价是额外的搬运带宽；也可与 FP8/FP4 量化叠加，concat 后的 2B 张量按同一权重计算，量化不改变合并公式的形式，只改变 <code>e_u</code>/<code>e_c</code> 的数值精度。</p>\n<p>具体例子：一个 batch 里混有短 prompt 与长 prompt，文本编码只跑一次并缓存，长 prompt 的 prefill 开销被摊到整个请求生命周期；每步只做一次 2B 前向，输出端两次切片加一次 FMA 组合，组合耗时相对 DiT 前向可忽略。若某步显存逼近上限，调度器应优先降 B 而非退回串行双前向——退回串行会让 launch 与调度开销重新翻倍，吞吐回到起点。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-18\">十八 · 公式的边界条件与数值稳定性推导</h3>\n<p>合并公式的等价性依赖两个隐含假设，工程上要逐条验证。假设一：DiT 对 batch 内样本严格独立。若归一化使用 batch 统计量或存在跨样本注意力，<em>f</em>([x;x]) 不再等于 [<em>f</em>(x);<em>f</em>(x)]，合并结果偏移，且偏移量随 B 增大而增大。假设二：两路输入除 condition 外完全一致——同一 latent、同一 timestep、同一随机噪声。若两路 latent 因调度不同步而分叉，差值 <em>x</em><sub>cond</sub>−<em>x</em><sub>uncond</sub> 混入了非引导因素，引导方向被污染。因此实现上必须保证两路共享同一份 latent 的拷贝，而不是各自独立演化。</p>\n<p>数值稳定性可从公式直接推。设 <em>x</em><sub>cond</sub> 与 <em>x</em><sub>uncond</sub> 的量级为 <em>M</em>，差值量级至多 2<em>M</em>，乘 <em>s</em> 后为 2<em>sM</em>，再与 <em>x</em><sub>uncond</sub> 相加，结果的动态范围约为 (1+2<em>s</em>)<em>M</em>。当 <em>s</em> 取较大值（高引导强度），FP8 的有限尾数在减法与乘法两步都会丢精度，FP4 更甚；把组合放到 FP32 可把误差压到可接受范围，代价是一次全张量 cast 的带宽往返，相对 2B 前向可忽略。另一个稳定性来源是两路输出的相关性：若 <em>x</em><sub>cond</sub>≈<em>x</em><sub>uncond</sub>（条件几乎不影响预测），差值是两个大数相减，有效位数骤降，此时低精度减法的相对误差被放大——这也是合并必须在高精度做的直接理由。</p>\n<p>系统代价上，边界条件失效的代价远高于精度代价。顺序错位导致方向反转，是“静默错误”：服务不报错、时延不变、吞吐不变，只有画质劣化，定位成本极高；batch 独立性假设被破坏则是“系统性偏移”，所有请求同等劣化。工程判断是：把顺序契约做成组装函数的硬断言，把 batch 独立性做成模型选型的前置检查，二者都不留在运行时靠观测发现。</p>\n<p>具体例子：某 DiT 变体在归一化中用了 batch 级统计，合并后 2B 前向的统计量与单样本不同，输出整体偏移，表现为画面偏灰；此时正确做法是关闭该归一化的 batch 统计或退回串行 CFG，而不是调 <em>s</em> 补偿。另一个例子：<em>s</em> 预设为高引导强度且模型以 FP8 计算，若组合误在 FP8 完成，差值溢出使部分通道饱和，画面出现硬边；把组合切到 FP32 后饱和消失，时延几乎不变。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-19\">十九 · 合并公式与缓存、调度的耦合推导</h3>\n<p>文本侧缓存与合并公式的耦合点在于：公式里的 <em>x</em><sub>cond</sub> 依赖 condition embedding，而 embedding 每步不变，因此每步重算 T5/CLIP 是纯浪费。把文本编码从步循环中提出来，缓存 <code>emb_c</code>/<code>emb_u</code>，每步只做 concat 与前向，长 prompt 场景省下的 prefill 开销可观。缓存的键是 prompt 哈希加负向模板标识，命中率取决于请求重复度；在线服务里同一 prompt 的多张出图、同一批次的模板复用都能命中。代价是缓存占显存，需按容量上限做 LRU 淘汰，且负向 embedding 与条件 embedding 必须成对缓存，否则拼接时缺一路。</p>\n<p>调度侧，合并公式把“每步两次前向”压成“每步一次前向”，连续批处理的粒度随之改变：调度器不再需要为 CFG 维护两套并行的 batch 队列，而是维护一份 2B 的合并队列。由此带来一个推导结论：合并后的有效批大小是 2B，显存峰值按 2B 计，而吞吐按 B 个请求计——容量规划时必须用 2B 的激活峰值去卡显存预算，用 B 去算 QPS。若按 B 估显存，上线即 OOM；若按 2B 估吞吐，则高估产能。这个“2B 显存、B 产能”的不对称是批合并最容易被忽略的规划陷阱。</p>\n<p>公式还限制了灵活性：<em>s</em> 在输出端合并，意味着同一合并批次内所有请求共享一个 <em>s</em>，无法按样本动态调。工程上的折中是按业务分层预设 <em>s</em>，把不同引导强度的请求分到不同合并批次，用批次划分换取 <em>s</em> 的差异化；代价是批次变小、M 维填充变差，吞吐回落。若业务确实需要逐样本动态 <em>s</em>，则合并公式要改成逐样本系数 <em>s</em><sub>i</sub> 的广播形式，组合仍是逐元素运算，但批次内 <em>s</em> 异质会让数值范围不一致，FP32 组合的必要性更强。</p>\n<p>具体例子：一个批次里 6 个请求用默认 <em>s</em>、2 个请求用高引导强度，若强行合并，高 <em>s</em> 请求的画质被低 <em>s</em> 拖累；正确做法是拆成两个合并批次分别跑，或对高 <em>s</em> 请求单独走串行路径。系统代价是拆批后每批 M 维变小、Tensor Core 利用率下降，但避免了画质事故。容量规划上，按 2B 峰值预留显存、按 B 计算 SLO 时延，是这套算法上线前的两条硬约束。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-20\">二十 · 批合并的边界条件与失效路径</h3>\n<p>合并前向的收益并非无条件成立，它由一条显存不等式约束：设单样本 latent 与激活峰值为 $m$，权重与 KV 常驻为 $W$，则合并可行需满足 $2B\\cdot m + W \\le M_{\\text{HBM}}$。Blackwell 单卡 HBM 容量固定，$m$ 随分辨率平方增长，因此高分辨率大 DiT 场景下 $2B$ 很快触顶——此时唯一出路是分块（tiling）把空间维切分后逐块前向，或把部分激活 offload 到主机内存，代价是每块引入额外的 HBM–PCIe 往返，端到端时延不再由 GEMM 主导而由搬运主导。判断阈值应落在部署前：以目标分辨率实测单样本激活峰值，反解出可拼的最大 $B$，再与 SLO 要求的并发比对，若 $B$ 不足以喂满 Tensor Core 的 M 维，合并的吞吐优势即被抵消。</p>\n<p>第二类失效来自索引契约。合并公式 $\\epsilon = \\epsilon_{\\mathrm{uncond}} + s(\\epsilon_{\\mathrm{cond}}-\\epsilon_{\\mathrm{uncond}})$ 依赖前半批恒为 uncond、后半批恒为 cond；一旦请求队列在 concat 时因动态批处理重排了顺序，或切分索引写成 $[B{:}2B]$ 与 $[{:}B]$ 错位，引导方向反转，输出表现为过饱和或语义漂移，且日志中张量形状完全合法，故障极难定位。工程上应把顺序作为不变量写进调度器：concat 由固定模板生成，切片索引与公式在同一函数内绑定，禁止跨模块传递裸 batch。</p>\n<p>第三类失效是灵活性的丧失。$s$ 在输出端合并，意味着同一次前向内所有样本共享同一引导强度，无法按请求动态调整；长尾请求需要更高 $s$ 换取语义对齐，批量请求则偏好较低 $s$ 保画质，二者混批时只能取折中。可行做法是在请求入口按业务分层预设 $s$ 并分组入批，牺牲部分拼批率换取画质一致性——这本身是一笔吞吐换质量的显式交易，须在容量规划中计入。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>触发机制</th><th>系统代价</th></tr></thead><tbody><tr><td>高分辨率大 DiT</td><td>$2B$ 激活峰值超 HBM</td><td>OOM，回退串行双前向，吞吐折半</td></tr><tr><td>concat 顺序错位</td><td>切分索引与公式不匹配</td><td>引导反向，输出不可用且难定位</td></tr><tr><td>$s$ 全局固定</td><td>输出端合并无法逐样本调</td><td>混批画质下降，需分组牺牲拼批率</td></tr></tbody></table>\n<h3 id=\"alg-cfg-batch-merge-sec-21\">二十一 · 请求形态与 2B 批的匹配关系</h3>\n<p>批合并的负载配方不是一条通用规则，而是一组约束的联立解。它要求请求形态具备三个特征：在线文生图、单请求时延主导 SLO、prompt 长度分布相对集中。原因在于合并后的前向张量在 batch 维是 2B，前半为无条件分支、后半为条件分支，两者共享同一份权重与同一组 kernel launch。只有当请求队列能稳定凑出 B 个样本、且每个样本都带一份可复用的 prompt embedding 时，2B 的 M 维才填得满。若请求到达稀疏、B 长期小于硬件的最佳 M 维，合并带来的调度开销减半仍成立，但 Tensor Core 利用率提升会被稀释，收益退化为“少一次 launch”而非“更饱满的 GEMM”。</p>\n<p>长度分布的影响体现在文本编码阶段。合并机制把 T5/CLIP 的编码从每步一次降为每请求一次，长 prompt 场景下这笔 prefill 开销的节省最可观；反之，若 prompt 普遍极短，编码成本本就可忽略，收益主要落在 DiT 前向的合并上。因此负载配方的第一条判断是：<strong>长 prompt 占比高、并发稳定、B 可拼到接近显存上限</strong>的在线服务，是批合并的甜点区。第二条判断是 SLO 形态——以单请求时延为主的服务，合并后每步只有一次前向，端到端时延的抖动来源减少；以吞吐为唯一目标、允许大排队的离线批处理，则更应关注 2B 下的显存峰值而非 launch 次数。</p>\n<div class=\"formula\">$$\\text{Throughput}\\approx\\frac{2B}{t_{\\text{fwd}}(2B)}\\ \\text{vs}\\ \\frac{B}{t_{\\text{fwd}}(B)}$$</div>\n<p>这个式子给出负载配方的量化骨架：合并后的吞吐是 2B 除以一次大前向的耗时，串行双前向是 B 除以一次小前向的耗时。收益全部来自 $t_{\\text{fwd}}(2B)$ 与 $t_{\\text{fwd}}(B)$ 的比值——当 2B 仍处于 MMA 利用率上升段时，比值小于 2，吞吐净赚；当 2B 已越过显存或 occupancy 的拐点，比值逼近甚至超过 2，收益消失。配方的工作就是把这个比值压在有利区间内。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-22\">二十二 · 并发与批大小的配方边界</h3>\n<p>B 的上界由显存峰值决定，而不是由请求队列长度决定。合并使激活显存翻倍：2B 的中间张量、注意力工作区、以及 concat 后按同一权重计算的 GEMM 输出，全部按两倍规模驻留。工程上应先测出单份 B 的峰值，再反推 2B 是否落在预算内；若超出，配方有两条路——降低 B 使 2B 回到预算内，或引入分块/offload 把峰值压回去。前者牺牲 M 维饱满度，后者牺牲单步时延，二者不可同时最优。</p>\n<p>并发维度还有一层容易被忽略的耦合：合并把“条件/无条件”从两个独立请求变成了同一请求内的两半，服务端的连续批处理调度器看到的是一个 2B 的条目而非两个 B 的条目。这意味着调度粒度变粗，队列中等待拼批的请求数需要至少为 B 才能稳定成批；若并发低于 B，调度器要么空转等待，要么以小于 B 的规模合并，前者增加排队时延，后者降低 GEMM 效率。配方上通常要求稳态并发不低于 2B 的量级，才能让拼批与执行重叠起来。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>配方取向</th><th>主要代价</th></tr></thead><tbody><tr><td>长 prompt 占比高、并发稳定</td><td>B 取显存允许的上限，2B 拼满</td><td>激活显存翻倍，需预留峰值余量</td></tr><tr><td>prompt 极短、请求稀疏</td><td>B 缩小，优先保时延</td><td>M 维不饱满，吞吐增益退化</td></tr><tr><td>高分辨率、大 DiT</td><td>配合分块或 offload，B 下调</td><td>单步时延上升，峰值压回预算</td></tr><tr><td>长尾请求与批量请求混跑</td><td>按业务分层预设 $s$，不追求单批统一</td><td>灵活性下降，画质与对齐难兼顾</td></tr></tbody></table>\n<p>具体例子：一个在线文生图服务，稳态并发为数十个请求，prompt 多为中长描述，DiT 规模中等。此时把 B 设为显存峰值允许的最大值、2B 一次前向，文本编码每请求只跑一次并缓存，每步仅一次 kernel launch，端到端时延的构成中调度开销占比显著下降。若同一服务把分辨率提高一档，2B 激活越过预算，配方必须转为下调 B 并叠加分块，此时吞吐增益让位于不 OOM 的硬约束。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-23\">二十三 · 负载不对时的三类失效</h3>\n<p>第一类是显存失效。高分辨率大 DiT 下，concat 后的 2B 张量使峰值翻倍，未配合分块或 offload 时直接触发 OOM，服务端 batch 被迫回退到串行双前向。回退不是无损的：它把已经按合并配方调好的调度、缓存、kernel 选择全部作废，吞吐与显存利用率同时跌回双低状态，且回退往往发生在请求高峰，抖动被放大。配方上应把“2B 峰值是否在预算内”作为上线前的硬门槛，而不是运行时的兜底分支。</p>\n<p>第二类是正确性失效。concat 顺序必须固定为前半 uncond、后半 cond，切分索引与合并公式一一对应。一旦顺序或索引错位，引导方向反转，输出画面过饱和或语义偏离 prompt，而日志里看到的只是一次正常前向，定位极难。这类失效的根因不在数值精度，而在数据布局约定；配方上应把 concat 顺序与切片索引写成同一处常量，禁止在两处各自维护。</p>\n<div class=\"formula\">$$\\epsilon = \\epsilon_{\\mathrm{uncond}} + s\\,(\\epsilon_{\\mathrm{cond}} - \\epsilon_{\\mathrm{uncond}})$$</div>\n<p>第三类是灵活性失效。引导尺度 $s$ 的合并在输出端完成，无法在中途按样本动态调整。长尾请求与批量请求共用同一 $s$ 时，画质与语义对齐难以兼顾：批量请求偏好的 $s$ 对长尾请求可能过强或过弱。配方上的应对是在请求入口按业务分层预设 $s$，把同一 $s$ 的请求聚到同一批，代价是队列被切成多个子队列，拼批效率下降，B 更难填满。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-24\">二十四 · 与量化、分块的联合配方</h3>\n<p>合并后的 2B 张量按同一权重计算，因此量化可与 FP8/FP4 叠加，concat 不改变权重的数值路径。但引导组合发生在输出端，$s$ 较大时数值动态范围变大，低精度下易溢出，组合必须保持在 FP32。这条约束与负载配方直接相关：$s$ 的分布由业务决定，若业务普遍使用大 $s$，则组合段的 FP32 开销成为固定成本，配方应把它计入单步时延预算，而不是当作可忽略的尾部。</p>\n<p>分块与 offload 是显存失效的主要对冲手段，但它们改变负载配方的形状。分块把高分辨率 latent 切成块分别前向，2B 的峰值被摊到块级，B 可以重新上调；代价是块间边界处理与额外的 kernel launch，合并省下的 launch 开销被部分抵消。offload 把部分激活搬到主机侧，峰值下降但单步时延上升，适合吞吐优先、时延宽松的负载。配方上应把“是否分块/offload”与“B 的取值”作为一对联合决策，而非先后独立的两个开关。</p>\n<p>具体例子：同一套合并配方在中分辨率下 B 取上限、不开分块，单步一次前向、文本编码一次缓存；切到高分辨率后，配方改为分块加 B 下调，2B 峰值回到预算内，但每步的 launch 次数随块数增加，合并的调度收益被稀释。此时若业务仍以单请求时延为 SLO，配方应优先保 B 而非保分块粒度。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-25\">二十五 · 规模上限与配方判断</h3>\n<p>规模上限由单卡显存峰值与并行拓扑共同决定。张量并行可以把权重与激活分摊到多卡，2B 的峰值随之按卡数摊薄，B 的上界被抬高；但合并后的前向仍是一次集合通信参与的 GEMM，通信量与 2B 成正比，卡数增加会引入新的时延项。配方上应把并行度视为扩大 B 的手段，同时把通信开销计入单步时延，避免“卡多了、B 大了、时延反而抖”的错配。</p>\n<p>与 CFG 蒸馏相比，批合并不改模型结构、无训练成本，这是它在配方上的优势；代价是显存峰值更高、$s$ 不可按样本动态调。因此配方的判断标准不是“合并是否总是更快”，而是“当前负载的显存预算能否容纳 2B、并发能否稳定填满 B、$s$ 分布能否按层聚合”。三者同时成立时合并是默认路径；任一不成立，就应退到串行双前向或蒸馏分支，而不是靠运行时兜底硬撑。</p>\n<p>最终落在工程判断上：负载配方的核心是把 B 与 2B 的显存峰值、并发水位、$s$ 分层三者对齐，并在上线前把 concat 顺序与切片索引固化为单一常量。合并的收益来自一次前向替代两次 launch 与两次小 batch GEMM，这个收益只在 2B 仍处于 MMA 利用率上升段时兑现；一旦 2B 越过显存拐点，配方必须主动下调 B 或引入分块，把峰值压回预算，否则回退到串行双前向的代价会吞掉全部收益。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-26\">二十六 · 负载配方：批合并只在“显存换调度”划算时成立</h3>\n<p>批合并的收益不是无条件的，它本质上是一笔交易：用显存峰值翻倍，换 kernel launch 与调度开销减半、GEMM 的 M 维更饱满。这笔交易只在特定请求形态下划算——在线文生图、单请求时延为主的 SLO、DiT 规模中等、显存有富余。此时把 [cond; uncond] 在 batch 维 cat 成 2B 一次前向，Tensor Core 利用率明显高于两次小 batch，实测吞吐提升 1.3–1.6 倍。反过来，一旦负载偏离这个配方，收益会迅速被代价吃掉。吞吐的账可以写成：$$\\text{Throughput}\\approx\\frac{2B}{t_{\\text{fwd}}(2B)}\\ \\text{vs}\\ \\frac{B}{t_{\\text{fwd}}(B)}$$ 只有当 $t_{\\text{fwd}}(2B)$ 显著小于 $2\\,t_{\\text{fwd}}(B)$（即大 batch 摊薄了 launch 与调度开销）时，合并才赢；若 2B 已经撞到显存墙、被迫降 batch 或分块，分母优势消失，合并就只剩显存代价。</p>\n<p>最直接的失效条件是显存。concat 后的 2B 张量使激活显存翻倍，高分辨率、大 DiT 下极易触发 OOM；未配合分块或 offload 时，服务端 batch 被迫回退到串行双前向，等于白做了一套合并逻辑还多背了复杂度。因此 B 的取值必须由显存峰值反推，而不是由请求并发数正推：先算出单步 2B 前向的激活峰值加上 KV/文本缓存，再留出 scheduler 与组合缓冲的余量，剩下的才是可用 B。量化（FP8/FP4）与分块/offload 是把这个峰值压回预算内的常规手段，但量化会牵出第二个边界——数值稳定性。</p>\n<p>引导组合发生在输出端，$\\epsilon=\\epsilon_{\\mathrm{uncond}}+s(\\epsilon_{\\mathrm{cond}}-\\epsilon_{\\mathrm{uncond}})$，$s$ 越大动态范围越大，低精度下易溢出，组合必须保持在 FP32。这意味着合并方案对 guidance scale 的分布敏感：$s$ 集中在温和区间时低精度路径稳，长尾请求用极端 $s$ 时就得走更高精度或额外缩放，吞吐随之回落。更硬的限制是灵活性——$s$ 固定在输出端合并，无法按样本在中途动态调整，只能在请求入口按业务分层预设。长尾请求与批量请求共用同一 $s$ 时，画质与语义对齐难以兼顾，这是合并相对串行双前向和 CFG 蒸馏的结构性劣势：蒸馏把 guidance 蒸进单分支、无此约束但要训练成本；合并零训练成本，却把灵活性让渡了出去。</p>\n<p>还有一类失效不体现在性能而在正确性：concat 顺序必须固定为前半 uncond、后半 cond，切分索引与合并公式一一对应。顺序或索引错位会让 guidance 方向反转，输出过饱和或语义偏离 prompt，且从日志上极难定位——因为张量形状、时延、吞吐全都正常。工程上应把 concat 顺序与切片写成同一处常量、在合并前后加形状与数值断言，而不是散落在调度与算子两侧。规模上限则由单卡显存峰值与并行拓扑共同决定：张量并行能摊开权重，却摊不开每卡的 2B 激活，跨卡切分 batch 又会引入通信，合并的调度优势被抵消。判断是否启用这套方案，看的是“2B 能否稳定装进单卡预算且 $s$ 分布可控”，两条任一不满足，就该退回串行双前向或改走蒸馏路线。</p>\n<h3 id=\"alg-cfg-batch-merge-sec-27\">二十七 · 硬件档位：按 2B 峰值显存反推卡型与并行度</h3>\n<p>部署配方的第一步不是选框架，而是把 CFG 批合并后的峰值显存算清楚，再反推硬件档位。合并后单次前向的输入是 2B 的 latent 张量，DiT 的激活显存、注意力工作区与权重驻留三者叠加，峰值近似随 2B 线性增长。设单样本在给定分辨率下的激活峰值为 $a$，权重与 KV/文本缓存驻留为 $W$，则单卡预算约束为</p>\n<div class=\"formula\">$$2B\\cdot a + W + M_{\\text{workspace}} \\le C_{\\text{HBM}}$$</div>\n<p>其中 $M_{\\text{workspace}}$ 是 tcgen05 MMA 的 TMEM 与异步拷贝缓冲占用。工程判断的顺序是：先固定分辨率与 DiT 规模，测出单样本 $a$，再用上式解出可用的 B 上限，最后决定是单卡跑还是切张量并行。B200 单卡 HBM 容量足以在中等 DiT、常规分辨率下把 B 拼到可用规模；一旦分辨率抬升使 $a$ 翻倍，2B 的乘积很快吃掉预算，此时要么降 B、要么上张量并行把 $W$ 与激活按卡分摊。张量并行的代价是每层 GEMM 后插入 all-reduce，NVLink 5 域内带宽足以让这部分开销隐藏在计算之后，但跨节点走 NCCL 时通信占比上升，2B 的收益会被吃掉一部分。因此拓扑选择的判据是：单卡能装下 2B 就绝不切并行，切并行只在 $2B\\cdot a$ 逼近容量上限时启用，且优先在 NVLink 域内切分。</p>\n<p>具体例子：一个中等规模 DiT 在 1024 分辨率下单样本激活约数 GB 量级，2B 拼接后激活翻倍，若权重驻留已占去相当比例，则 B 只能取较小值；把分辨率提到更高档位后同一张卡上的 B 被迫减半，吞吐回落。此时把张量并行度设为 2，权重与激活各分一半，B 得以恢复，代价是每步多一次域内规约。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-28\">二十八 · 并行拓扑：把 concat 维放在最不该被切的位置</h3>\n<p>批合并的张量形状是 $[2B, \\ldots]$，其中前 B 行是无条件、后 B 行是条件。并行切分时必须保证这个语义边界不被破坏：序列并行切的是 token 维，不影响 batch 语义；张量并行切的是权重维，两半样本走同一份切分权重，合并公式在输出端仍然成立；而数据并行或流水并行若把 2B 拆到不同设备，切分索引与合并公式的对应关系就要跨设备维护，日志里一旦错位就是 guidance 方向反转。因此拓扑约束可以写成一句工程规则：concat 维必须完整落在同一组执行同一份权重的设备上，跨设备只允许切权重与序列。</p>\n<p>在 SM100 的 2-SM MMA 模式下，一次 MMA 由两个 SM 协作完成，M 维的饱满度直接决定 Tensor Core 利用率。2B 拼接恰好把 M 维填厚，这是合并带来吞吐提升的硬件根源；若再叠加张量并行，每卡的 M 维仍是 2B，只是 N/K 被切分，MMA 形状依然饱满。伪代码层面的拓扑决策可以写成：</p>\n<div class=\"formula\">$$\\text{topology}=\\begin{cases}\\text{single-GPU}, &amp; 2B\\cdot a+W\\le C\\\\ \\text{TP}=k\\text{ intra-NVLink}, &amp; 2B\\cdot a+W&gt; C,\\ k=\\lceil (2B\\cdot a+W)/C\\rceil\\end{cases}$$</div>\n<p>代价面：TP 度每加一，每步多一次 all-reduce，延迟增加的量级取决于 hidden size 与域内带宽；在 NVLink 5 域内这部分通常被 GEMM 掩盖，但 TP 跨节点后 NCCL 的规约时延会直接进入关键路径，单请求时延 SLO 收紧时不可接受。具体例子：同一 DiT 在单卡上 B 受限导致吞吐上不去，改 TP=2 后 B 恢复、吞吐回升，但单请求时延因规约增加而略微变长，在线服务需在吞吐与尾延迟之间取平衡点。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-29\">二十九 · 量化方案：concat 张量同权重、合并留 FP32</h3>\n<p>批合并与量化叠加时有一条硬约束：2B 张量必须走同一份量化权重与同一套缩放因子，否则前后两半的数值基准不一致，合并公式里的差值 $x_{\\text{cond}}-x_{\\text{uncond}}$ 就失去意义。因此量化方案的选择不以“哪半更省”为判据，而以“整批是否能在同一精度下稳定跑完”为判据。GEMM 与注意力可以走 FP8 或 NVFP4，权重按块量化、激活按动态缩放，这是 Blackwell 上成熟的路径；但输出端的引导组合必须留在 FP32，因为 $s$ 较大时 $s\\,(x_{\\text{cond}}-x_{\\text{uncond}})$ 的动态范围被放大，低精度累加会溢出或丢有效位。</p>\n<p>工程上的分层是：DiT 主干 GEMM 与注意力用低精度，文本编码器输出缓存保持较高精度以免跨步复用时误差累积，引导组合在 FP32 完成后再写回 latent。代价面：低精度 GEMM 提升吞吐并压低权重驻留，使上式中的 $W$ 变小、B 上限抬高；但 FP4 路径需要校准，校准数据若只覆盖单分支分布，2B 拼接后的激活分布可能超出缩放范围，表现为画面过饱和。具体例子：某服务把主干切到 FP8、合并留 FP32，B 上限因权重驻留下降而提高一档，吞吐随之上升；若把合并也降到 FP8，高 $s$ 请求出现饱和伪影，回退方案是把合并单独提出到 FP32 kernel。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-30\">三十 · KV 与条件缓存策略：跨步复用文本 embedding，负向单独驻留</h3>\n<p>批合并省掉的是每步重算文本编码器的开销，前提是 embedding 被正确缓存。请求到达时跑一次文本编码器，产出条件 embedding 与负向（空 prompt）embedding，两者都写入缓存并按请求 ID 索引；此后每个去噪步只做 concat 与前向，不再触碰 T5/CLIP。缓存的生命周期与请求绑定，请求结束即释放，避免长 prompt 场景下缓存膨胀挤占激活预算。负向 embedding 对所有请求相同，可以做成全局单例常驻，进一步压掉一份驻留。</p>\n<p>KV 策略在这里的含义与自回归解码不同：DiT 的“KV”主要是注意力中的 key/value 投影中间结果与文本交叉注意力的缓存。跨步复用的是文本侧，图像侧的注意力工作区每步重算，因为 latent 在变。显存账本上，文本缓存是常数项，激活是随 2B 变化的变量项，前者可以放心常驻，后者必须与 B 联动。代价面：缓存命中使长 prompt 的 prefill 开销从每步一次降为每请求一次，这是合并之外的第二重收益；但缓存条目若按请求粒度无上限增长，显存会被慢慢吃掉，需要设上限并按 LRU 淘汰。具体例子：长 prompt 在线服务中，未缓存时每步都要跑文本编码器，时延被 prefill 主导；缓存后 prefill 只发生一次，单请求时延明显下降，且 2B 前向的占比上升，吞吐更稳定。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-31\">三十一 · 调度参数：B 的动态上限、s 的分层预设与回退路径</h3>\n<p>调度层要把前四节的约束翻译成运行参数。核心参数是 B 的动态上限：调度器在准入时按当前分辨率与 DiT 档位查表得到 $B_{\\max}$，再按队列深度取 $\\min(\\text{队列需求}, B_{\\max})$，凑成 2B 批次下发。B 不应固定，因为分辨率与请求形态会漂移；固定 B 在高分辨率请求到来时直接 OOM。第二个参数是 guidance scale 的分层预设：合并发生在输出端，中途无法按样本改 $s$，所以 $s$ 必须在请求入口按业务分层写入，同一批次内共用同一 $s$，长尾请求与批量请求分流到不同队列。</p>\n<p>第三个参数是回退阈值：当 2B 峰值逼近容量上限时，调度器应主动降 B 或切回串行双前向，而不是等 OOM 触发。串行双前向的吞吐低于合并，但显存峰值减半，是保命路径。伪代码思路：</p>\n<div class=\"formula\">$$\\text{dispatch}(q)=\\begin{cases}\\text{merge}(2B), &amp; \\text{peak}(2B)\\le \\alpha C\\\\ \\text{serial-dual}, &amp; \\text{peak}(2B)&gt;\\alpha C\\end{cases},\\quad \\alpha&lt;1$$</div>\n<p>$\\alpha$ 留出的余量用于吸收激活的瞬时波动与工作区开销。代价面：回退到串行后 kernel launch 与调度开销翻倍，GEMM 的 M 维变薄，Tensor Core 利用率下降，吞吐回落；但服务不中断。具体例子：高峰期队列里混入高分辨率请求，$B_{\\max}$ 骤降，调度器把批次拆小并对超阈值请求走串行路径，整体吞吐下降但尾延迟 SLO 守住；若强行合并，OOM 会让整个批次失败重试，代价更大。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-32\">三十二 · 可复现的配置思路：从单样本基准到整机配方</h3>\n<p>把上述决策串成一条可复现的路径，顺序是固定的。第一步，固定分辨率与 DiT 规模，跑单样本前向，测出激活峰值 $a$ 与权重驻留 $W$，这是所有后续计算的输入。第二步，用容量约束解出 $B_{\\max}$，并留出 $\\alpha$ 余量。第三步，判断单卡是否装得下 2B：装得下则拓扑为单卡，装不下则在 NVLink 域内切 TP，切分度按容量缺口取整。第四步，量化分层：主干低精度、合并 FP32、文本缓存较高精度，并用覆盖双分支分布的校准集验证。第五步，缓存策略：文本 embedding 按请求缓存、负向全局常驻、条目数设上限。第六步，调度参数：B 动态上限、$s$ 分层预设、回退阈值 $\\alpha$。每一步的产出都是下一步的输入，任何一步的测量偏差都会沿链条放大，所以第一步的单样本基准必须可重复。</p>\n<p>这套配方的工程判断落在一点上：CFG 批合并的收益来自 M 维饱满与 kernel launch 减半，代价来自 2B 的显存峰值；部署配方本质上是在容量约束下把 B 推到尽可能大，同时用拓扑、量化、缓存三条路径压低峰值与驻留，用调度参数兜住越界。配方是否成立，看的是在目标 SLO 下 $B_{\\max}$ 能否稳定维持，而不是峰值吞吐的瞬时数字。当分辨率或 DiT 规模变化时，重跑第一步即可重新解出整条链条，配方因此可复现而非一次性调参。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-33\">三十三 · 部署配方的边界：2B 显存峰值、并行拓扑与量化叠加</h3>\n<p>这套配方的硬件档位由「单卡显存峰值能否容纳 2B 张量」反推，而不是先选卡再调参。合并后激活显存约为串行双前向的两倍，B 的上界满足 <span class=\"formula\">$$2B\\cdot A_{\\text{act}}(H,W)+W_{\\text{weights}}+W_{\\text{KV}} \\le \\text{HBM}_{\\text{usable}}$$</span>，其中 $A_{\\text{act}}$ 随分辨率线性增长。因此高分辨率、大 DiT 是首要失效条件：一旦 2B 越界，服务端 batch 被迫回退到串行双前向，吞吐立刻掉回基线。工程上的做法是先把分块注意力或 VAE 解码 offload 把峰值压回预算，再决定 B；张量并行只在单卡装不下权重时才引入，因为 TP 切分不减小每卡激活的 batch 维，反而增加 all-reduce 通信，对延迟型 SLO 不利。</p>\n<p>量化可与 FP8/FP4 叠加，concat 后的 2B 张量按同一套权重计算，权重只需驻留一份，这是合并相对串行双前向的隐性收益。但引导组合必须留在 FP32：$s$ 较大时 $\\epsilon_{\\text{cond}}-\\epsilon_{\\text{uncond}}$ 的动态范围被放大，低精度下累加与减法易溢出，表现为高对比区域出现色块或饱和。KV 策略上，文本侧 embedding 与负向 embedding 只算一次并跨步复用，真正占显存的是每步的 2B 激活而非 KV；调度参数应把「单请求时延」作为主约束，按 2B 组织微批，让 GEMM 的 M 维保持饱满，同时把 kernel launch 与调度开销减半。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>高分辨率大 DiT，2B 越界</td><td>OOM，回退串行，吞吐降回基线</td><td>分块 / offload 压峰值，再定 B</td></tr><tr><td>concat 顺序或切分索引错位</td><td>guidance 方向反转，画面过饱和</td><td>固定前半 uncond、后半 cond，索引与公式对齐</td></tr><tr><td>$s$ 固定在输出端</td><td>长尾与批量请求共用同一 $s$，画质难兼顾</td><td>请求入口按业务分层预设 $s$</td></tr></tbody></table>\n<p>可复现的配置思路是：先按目标分辨率测出单份激活峰值，乘以二得到 2B 预算，据此定 B 与是否分块；文本编码器只跑一次并缓存双向 embedding；每步固定 concat 顺序送入 DiT，输出切片后在 FP32 做 $\\epsilon=\\epsilon_{\\text{uncond}}+s(\\epsilon_{\\text{cond}}-\\epsilon_{\\text{uncond}})$ 并写回单份 latent；量化先开权重 FP8、激活保持组合段 FP32，观察溢出再决定是否下探 FP4。这套配方不改模型结构、无训练成本，但把灵活性让渡给了显存：无法按样本动态调 $s$，规模上限由单卡峰值与并行拓扑共同封顶。</p>\n<h3 id=\"alg-cfg-batch-merge-sec-34\">三十四 · 显存峰值：2B 张量与激活翻倍的真实账本</h3>\n<p>批合并把两次前向压成一次，代价首先记在显存账上。concat 之后送入 DiT 的输入张量在 batch 维是 2B，而 DiT 的激活显存近似随 batch 线性增长：每层注意力的 Q/K/V、FFN 中间激活、以及残差缓冲都按 2B 分配。设单样本在某一分辨率的激活峰值为 $A$，则合并前串行双前向的瞬时峰值约为 $A$（两次前向不重叠），合并后约为 $2A$ 再加上 concat 缓冲本身。工程上真正致命的不是权重，而是峰值——权重是常量，激活是随分辨率平方增长的变量。</p>\n<p>以潜空间分辨率 $H\\times W$ 为例，patch size 为 $p$ 时序列长度 $N=HW/p^2$，注意力激活按 $O(N^2)$ 走（未上 FlashAttention 类核时），上了分块注意力后按 $O(N\\cdot c)$ 走，$c$ 为分块窗口。分辨率翻倍，$N$ 变四倍，激活的绝对量级跳一个档；此时 2B 的 concat 往往就是压垮预算的最后一根稻草。Blackwell 上 SM100 的 TMEM 与 tcgen05 让单次 MMA 能吃更大的 M 维，但这不改变激活驻留显存的物理事实——TMEM 是计算暂存，不是激活仓库。</p>\n<p>具体例子：中等规模 DiT 在 1024×1024 潜空间、B=4 时激活峰值尚在单卡预算内，合并成 2B=8 后峰值逼近上限；若把分辨率推到更高档位，同一张卡上 2B=8 直接触发 OOM，服务端被迫回退串行双前向，吞吐掉回合并前的水平。这就是规模上去以后第一个崩点：不是算力不够，是显存峰值先撞墙。应对只能是与分块、offload、量化三者叠加，把 2A 压回预算内，而这三者各自又引入新的带宽与延迟代价，见后文。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-35\">三十五 · 带宽：显存往返与权重流的双重压力</h3>\n<p>合并的收益之一是减少 kernel launch 与显存往返：串行双前向每步要两次把 latent 读进读出、两次走完整权重流；合并后一次前向走一遍权重，权重带宽消耗减半。但激活侧的带宽并没有减半——2B 的激活写回、读出、再切片，读写总量随 batch 翻倍而翻倍。于是带宽账本出现分化：权重带宽省一半，激活带宽翻一倍，净效果取决于模型是权重主导还是激活主导。</p>\n<p>对 DiT 这类权重占比高、单步计算密集的模型，权重流是显存带宽的主要消费者，合并的净带宽收益为正；对高分辨率、深序列的场景，激活带宽反超权重带宽，合并反而加重带宽负担。Blackwell 的 HBM 带宽提升缓解了绝对量，但不改变比例关系。更隐蔽的一层是 concat 缓冲：把两路 latent 拼成 2B 需要一次显存拷贝，切片合并又需要一次读写，这两次搬运在每步都发生，属于纯开销。</p>\n<div class=\"formula\">$$\\text{BW}_{\\text{merge}} \\approx \\text{BW}_{W} + 2\\,\\text{BW}_{A},\\quad \\text{BW}_{\\text{serial}} \\approx 2\\,\\text{BW}_{W} + 2\\,\\text{BW}_{A}$$</div>\n<p>上式给出定性判断：当 $\\text{BW}_W &gt; \\text{BW}_A$ 时合并占优，反之合并的带宽优势被激活翻倍吃掉。工程判断是：先在目标分辨率上测出权重流与激活流的占比，再决定是否值得合并，而不是无条件合并。一个具体做法是把 concat 与切片融进相邻 kernel，避免独立拷贝——这一步在 Triton 或 CUTLASS 里做 fusion，能把每步两次搬运省掉一次。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-36\">三十六 · 通信：张量并行下的 2B 切分与集合通信放大</h3>\n<p>单卡放不下时上张量并行，合并的 2B 张量要按 TP 切分，问题随之变形。串行双前向时，两次前向各自做一遍 all-reduce；合并后一次前向做一遍 all-reduce，但通信量按 2B 计，等于把两次小 all-reduce 合成一次大 all-reduce。集合通信的固定开销（启动延迟、同步）减半，但传输字节数不变，甚至因 concat 对齐而略增。在 NVLink 5 域内，固定开销占比高的小消息场景收益明显；跨节点、走 NIXL 或 NCCL 的拓扑上，字节数主导，合并的通信收益趋近于零。</p>\n<p>更要命的是负载均衡：2B 在 TP 组内切分时，若 B 不能被 TP 度整除，或 concat 后前半 uncond、后半 cond 的切分边界与 TP 切分边界错位，就会出现某些 rank 多算、某些 rank 空转。工程上要求 2B 对 TP 度整除，且切分索引与合并公式一一对应——这条约束在部署配方里已经提过，但在规模上去以后它是通信效率的硬前提。一个具体例子：TP=8、B=6 时 2B=12 不能被 8 整除，切分后各 rank 的 M 维不齐，GEMM 的尾部浪费叠加通信同步，实际吞吐低于理论值；改成 B=8 使 2B=16 整除后，M 维饱满，通信与计算重叠才真正生效。</p>\n<p>功耗侧同样受影响：合并后单次前向的瞬时功耗更高（2B 的 MMA 同时点亮更多 SM），但总能耗未必上升——kernel launch 与调度开销减半、权重流减半，单位请求的能耗通常下降。真正的功耗风险在峰值：2B 前向把更多 SM 推到高频，若散热或功耗墙受限，GPU 会降频，尾延迟反而恶化。这是合并在高密度部署下的隐性代价。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-37\">三十七 · 吞吐公式：大 batch 的 MMA 利用率与收益上限</h3>\n<p>合并的吞吐收益来自 M 维饱满。Blackwell 的 tcgen05 MMA 在 M 维较大时利用率高，小 batch 的 GEMM 有大量尾部浪费；把两次 B 拼成 2B，M 维翻倍，Tensor Core 的有效占用上升。用公式表达两种组织的吞吐对比：</p>\n<div class=\"formula\">$$\\text{Throughput}\\approx\\frac{2B}{t_{\\text{fwd}}(2B)}\\ \\text{vs}\\ \\frac{B}{t_{\\text{fwd}}(B)}$$</div>\n<p>若 $t_{\\text{fwd}}(2B) &lt; 2\\,t_{\\text{fwd}}(B)$，合并即胜出。实测吞吐提升 1.3–1.6 倍，这个区间的上界取决于两件事：一是 2B 是否仍在 MMA 的高效区间（batch 太大反而因寄存器压力与 occupancy 下降而劣化），二是显存峰值是否允许 2B 跑满。规模上去以后，收益先被显存卡住——B 受峰值约束无法继续放大，2B 停在某个值上，吞吐曲线走平；再往上只能靠 TP 扩卡，而 TP 又引入通信开销，收益被摊薄。这就是第二个崩点：吞吐的规模上限由单卡显存峰值与并行拓扑共同决定，不是由算力决定。</p>\n<p>具体例子：单卡上 B=4 合并成 2B=8 时吞吐提升明显；想把 B 推到 8 使 2B=16，显存峰值超预算，只能改 TP=2，此时每卡仍是 2B=8 的激活，但多了 all-reduce，端到端吞吐的提升幅度收窄。工程判断是：先找单卡显存允许的最大 2B，再评估是否值得为更大的 2B 付出 TP 通信代价。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-38\">三十八 · 尾延迟：合并放大 batch 内的最长路径</h3>\n<p>在线服务的 SLO 以单请求时延为主，合并对尾延迟的影响是双向的。好处是 kernel launch 与调度开销减半，单步固定开销下降，小请求的时延改善；坏处是合并把请求绑成一个 2B 的同步单元——一次前向必须等 2B 全部算完，batch 内任一请求的额外计算（更长 prompt 的文本编码、更高分辨率的 latent）都会拖长整批的完成时间。尾延迟由 batch 内最慢的那条路径决定，而不是平均值。</p>\n<p>文本编码侧的缓存是缓解手段：prompt embedding 与负向 embedding 跨步复用，长 prompt 的 prefill 只算一次，不进入每步的关键路径。但文本编码发生在请求入口，若入口处串行排队，长 prompt 仍会推高首步时延。工程上要把文本编码与 DiT 前向解耦成两级流水，让 embedding 缓存先于 batch 组装完成，否则合并的同步单元会把 prefill 的抖动传导到每一步。</p>\n<p>另一个尾延迟来源是 guidance scale 固定在输出端合并：无法按样本动态调 $s$，长尾请求与批量请求共用同一 $s$，画质与语义对齐难以兼顾。若业务需要分层 $s$，只能在请求入口按业务分层预设，把不同 $s$ 的请求分到不同 batch——这又拆碎了 batch，抵消了合并的调度收益。规模上去以后，这是第三个崩点：尾延迟与 batch 粒度之间的矛盾，在请求形态异构时无法靠单一合并策略化解。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-39\">三十九 · 崩点排序与工程判断</h3>\n<p>把五个维度按规模上去以后的崩溃顺序排：显存峰值最先崩，因为它是硬墙，OOM 直接让服务回退；其次是吞吐上限，B 被峰值卡死后吞吐走平；第三是尾延迟，异构请求把同步单元拖长；通信与带宽在单卡场景下排在后面，只有上 TP 或高分辨率时才成为主导。功耗与降频是隐性项，在高密度机架里可能提前触发。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>合并的代价</th><th>先崩的条件</th><th>缓解手段</th></tr></thead><tbody><tr><td>显存</td><td>激活峰值约 2A</td><td>高分辨率大 DiT</td><td>分块、offload、量化</td></tr><tr><td>带宽</td><td>激活流翻倍</td><td>深序列激活主导</td><td>concat/切片 fusion</td></tr><tr><td>通信</td><td>2B 集合通信</td><td>TP 跨节点、2B 不整除</td><td>对齐 TP 度、NVLink 域内</td></tr><tr><td>吞吐</td><td>B 受峰值约束</td><td>单卡 2B 到顶</td><td>TP 扩卡、权衡通信</td></tr><tr><td>尾延迟</td><td>同步单元放大最长路径</td><td>请求形态异构</td><td>embedding 缓存前置、分层 batch</td></tr></tbody></table>\n<p>工程判断落在具体机制上：合并的收益不是无条件的，它把“两次小前向”换成“一次大前向”，本质是用显存峰值换 MMA 利用率与调度开销。规模上去以后，先测目标分辨率下的激活峰值与权重/激活带宽占比，再决定 2B 的上限；上限确定后，用 TP 度整除约束与 embedding 缓存前置把通信与尾延迟的抖动压住。若峰值无法压回预算，回退串行双前向不是失败，而是把代价从显存换回调度——这个交换在显存紧张的部署里往往是正确的。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-40\">四十 · 规模上去以后，先崩的是显存峰值而不是算力</h3>\n<p>批合并把两次前向压成一次 2B 的 DiT 前向，收益来自 GEMM 的 M 维变饱满与 kernel launch 减半，但代价立刻体现在激活显存上：concat 后的 2B 张量按同一份权重计算，中间激活、attention 工作区、归一化缓冲全部按 2B 规模分配，峰值相对串行双前向直接翻倍。设单样本激活占用为 $a$、权重与 KV 为 $W$，则峰值近似为 $M_{\\text{peak}}\\approx 2B\\cdot a+W$，而串行方案只有 $B\\cdot a+W$。在中等 DiT、常规分辨率下 $W$ 占比可观，翻倍尚可吸收；一旦分辨率上去、DiT 变深，$a$ 的增长快于 $W$，2B 项主导峰值，OOM 先于算力瓶颈出现。此时服务端的典型退化路径不是降级画质，而是 batch 被迫回退到串行双前向，吞吐掉回原点，且调度器在两种模式间反复切换，尾延迟抖动被放大。</p>\n<p>第二处先崩的是带宽与通信，而不是 Tensor Core。合并后单次前向要搬运 2B 的输入输出与中间张量，HBM 往返量近似翻倍；在张量并行下，2B 的激活切分意味着 all-reduce/all-gather 的消息尺寸同步翻倍，NVLink 上的通信时间随消息大小近似线性增长，通信与计算的重叠窗口被压缩。功耗侧同样受牵连：大 batch 把 SM 占空比推高，单卡功耗贴近上限，机架级功率预算成为隐性约束，尤其在 NVL72 这类高密度部署里，功率封顶会反过来限制可拼的 B。文本 embedding 跨步复用确实省掉了每步重算 T5/CLIP 的 prefill，但那只削减了固定开销，改变不了每步 2B 激活搬运这一主项。</p>\n<p>尾延迟与灵活性是第三处边界。合并发生在输出端，引导组合 $\\hat{x}=x_{\\text{uncond}}+s\\,(x_{\\text{cond}}-x_{\\text{uncond}})$ 必须等 2B 前向整体完成后才能切片执行，因此单请求时延由最大 batch 的前向时间决定，长尾请求被短请求拖住；同时 $s$ 无法按样本在中途动态调整，只能在请求入口按业务分层预设，长尾与批量请求共用同一 $s$ 时画质与语义对齐难以兼顾。数值上，$s$ 偏大时动态范围扩张，低精度下组合步骤易溢出，必须把合并保持在 FP32，这又增加一次精度转换的带宽开销。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先触及的瓶颈</th><th>工程应对</th></tr></thead><tbody><tr><td>分辨率/DiT 深度上升</td><td>2B 激活峰值，OOM</td><td>分块 attention、激活 offload、与 FP8/FP4 叠加压峰值</td></tr><tr><td>张量并行度上升</td><td>通信消息翻倍，重叠窗口变窄</td><td>限制单卡 2B 上限，按拓扑重划 B</td></tr><tr><td>机架功率封顶</td><td>SM 占空比触顶，B 被功率反压</td><td>按功率预算而非显存预算定 B</td></tr><tr><td>请求长度方差大</td><td>尾延迟被最大 batch 绑定</td><td>按 $s$ 与分辨率分层排队，隔离长尾</td></tr></tbody></table>\n<p>判断很直接：批合并的规模上限由单卡显存峰值与并行拓扑共同决定，而不是由 Tensor Core 吞吐决定。把 B 定在显存预算的七成以内、把合并固定在 FP32、把 concat 顺序与切分索引做成编译期常量校验，比继续加大 batch 更能守住吞吐与尾延迟。</p>\n<h3 id=\"alg-cfg-batch-merge-sec-41\">四十一 · 精度失败：从 FP32 组合点向外扩散的污染链</h3>\n<p>批合并把引导组合从“两次前向之间”挪到了“一次前向之后”，这个位置变化本身不引入数值问题，但它把原本隔离在两条分支里的动态范围压进了同一张量。当 <span class=\"formula\">$$s$$</span> 取较大值（业务上常见的高引导档位），<span class=\"formula\">$$x_{\\text{cond}}-x_{\\text{uncond}}$$</span> 的差值被放大 <span class=\"formula\">$$s$$</span> 倍后再叠加到 <span class=\"formula\">$$x_{\\text{uncond}}$$</span> 上，组合结果的幅值可以显著超出任一分支单独的范围。若这一步在 FP16/BF16 下做，溢出与下溢会同时出现：大 <span class=\"formula\">$$s$$</span> 处饱和成 inf，小差值处被舍入抹平，表现为画面高对比区域出现色块、暗部细节丢失、语义对齐漂移。</p>\n<p>诊断的关键是把组合点钉死在 FP32。工程上要求 DiT 前向输出切片后先 upcast 到 FP32，做 <span class=\"formula\">$$\\hat{x}=x_{\\text{uncond}}+s\\,(x_{\\text{cond}}-x_{\\text{uncond}})$$</span>，再决定是否 downcast 回低精度进入 scheduler。这与量化路径直接耦合：NVFP4/FP8 的 GEMM 输出本身带量化误差，若组合也在低精度做，误差被 <span class=\"formula\">$$s$$</span> 线性放大而非抵消。监控手段是在组合前后各埋一个统计探针，记录 <span class=\"formula\">$$\\max|\\hat{x}|$$</span>、inf/nan 计数与 <span class=\"formula\">$$\\mathrm{std}(x_{\\text{cond}}-x_{\\text{uncond}})$$</span> 的滑动分位数；一旦某档 <span class=\"formula\">$$s$$</span> 下 inf 计数非零，说明该档位与当前量化配置不兼容，应回滚到 FP32 组合或对该档位降 <span class=\"formula\">$$s$$</span>。代价是组合张量在 FP32 下占用的显存与带宽翻倍，对高分辨率 latent 是一笔实打实的开销，通常用分块组合把峰值摊平。</p>\n<p>具体例子：同一 prompt 在 <span class=\"formula\">$$s=7$$</span> 档位下，FP16 组合输出出现局部过饱和，切到 FP32 组合后消失，而 DiT 主干仍跑 FP8——说明污染源只在组合点，不在 GEMM。这类定位靠“只改组合精度、其余不动”的单变量回滚即可完成。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-42\">四十二 · OOM：峰值翻倍与回退路径的确定性</h3>\n<p>concat 成 <span class=\"formula\">$$2B$$</span> 后，激活显存按 batch 线性翻倍，这是批合并最硬的代价。OOM 不是随机事件，它由三个量决定：单样本激活字节数 <span class=\"formula\">$$a$$</span>、批大小 <span class=\"formula\">$$B$$</span>、以及分块/offload 后仍驻留显存的常驻部分 <span class=\"formula\">$$R$$</span>。峰值近似为 <span class=\"formula\">$$2B\\cdot a + R$$</span>，调度器必须在入队前用这个式子做准入判断，而不是等 CUDA 抛错再补救。</p>\n<p>监控要分两层。第一层是准入层的预估：按当前分辨率、DiT 规模、量化档位查表得到 <span class=\"formula\">$$a$$</span>，与显存预算比较，超限的请求不进 2B 批。第二层是运行层的实测：用显存水位采样与 <span class=\"formula\">$$2B$$</span> 张量分配失败计数做告警，区分“瞬时峰值”与“泄漏式增长”——后者往往来自文本 embedding 缓存未按请求释放。回滚路径必须是确定性的：检测到 OOM 后，该批立即降级为串行双前向（两次 <span class=\"formula\">$$B$$</span> 前向），吞吐掉回合并前的水平但不丢请求；同时把触发 OOM 的 (分辨率, DiT 规模, 量化档) 三元组写入降级名单，后续同类请求直接走串行路径，避免反复触发。</p>\n<p>代价上要算清楚：串行回退把 kernel launch 与调度开销翻倍、GEMM 的 M 维减半，Tensor Core 利用率下降，端到端时延上升；但相比请求失败重试，这是更优的工程选择。具体例子：高分辨率档位下 <span class=\"formula\">$$2B$$</span> 峰值超出预算，服务端把该档位固定为串行双前向并对 latent 做分块，峰值压回预算内，代价是该档位吞吐低于合并路径——这是一个用吞吐换可用性的显式取舍，必须写进容量规划而不是临时打补丁。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-43\">四十三 · 批抖动：2B 拼接下的批形不稳</h3>\n<p>批合并把调度单位从 <span class=\"formula\">$$B$$</span> 变成 <span class=\"formula\">$$2B$$</span>，但请求到达是泊松式的，连续批处理在每一步都要重新拼批。抖动来自两个方向：一是批未拼满，<span class=\"formula\">$$2B$$</span> 实际只填了 <span class=\"formula\">$$2B'$$</span>，大 batch 的 MMA 利用率优势被稀释；二是拼接顺序被打乱，前半 uncond、后半 cond 的固定布局被动态批调度破坏，切分索引与合并公式错位。</p>\n<p>机制上要求批调度器把“一个逻辑请求”映射为“一对相邻槽位”，槽位对在 batch 维上连续且顺序固定，合并时按槽位对索引切片而非按绝对前半/后半。伪代码思路：<span class=\"formula\">$$\\text{for } i \\text{ in } [0,B):\\ \\hat{x}_i = x_{2i} + s_i\\,(x_{2i+1}-x_{2i})$$</span>，其中偶数槽为 uncond、奇数为 cond。这样即使批未满、即使槽位对之间有空隙，组合仍正确。代价是槽位对齐带来显存碎片，需要预分配固定形状的 <span class=\"formula\">$$2B_{\\max}$$</span> 缓冲并按槽位写入，牺牲一点显存换批形稳定。</p>\n<p>监控批抖动看两个指标：每步实际填充率 <span class=\"formula\">$$2B'/2B_{\\max}$$</span> 的分布，以及相邻步之间批组成的变动率。填充率长期偏低说明 <span class=\"formula\">$$B_{\\max}$$</span> 设得过大或到达率不足，应下调批上限；变动率高则说明调度窗口太短，需要拉长拼批等待窗口。具体例子：在线文生图流量低谷时填充率掉到很低，合并路径的 GEMM M 维不饱满，此时把批上限调低、甚至对小批直接走串行双前向，反而比硬拼 2B 更省。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-44\">四十四 · 路由不均与尾延迟尖刺</h3>\n<p>批合并本身不引入路由，但它与多副本/多卡部署叠加时会把不均衡放大：不同副本的 <span class=\"formula\">$$s$$</span> 档位、分辨率档位不同，导致单副本的 <span class=\"formula\">$$2B$$</span> 峰值与计算量差异显著，负载均衡若只看请求数不看“批成本”，就会把重档请求堆到同一副本上，形成路由不均。尾延迟尖刺的典型成因是重档请求恰好拼进一个已经接近显存上限的批，触发 OOM 回退，该批从合并路径跌到串行路径，时延骤增。</p>\n<p>诊断要把尾延迟拆到批粒度：记录每个批的 <span class=\"formula\">$$2B$$</span> 实际大小、<span class=\"formula\">$$s$$</span> 档位、是否发生回退，按分位数看 P99 批的组成。若 P99 批集中在某一 <span class=\"formula\">$$s$$</span> 档或某一分辨率档，说明准入与路由没有按成本分层。工程判断是：路由权重用 <span class=\"formula\">$$2B\\cdot a$$</span> 而非请求数，重档请求单独排队、单独限流，避免与轻档混拼。代价是重档请求的排队时延上升，但整体尾延迟收敛——这是用分层换稳定。</p>\n<p>具体例子：长 prompt 场景下文本编码 prefill 开销可观，若长 prompt 请求与短 prompt 混在同一批，短请求被长请求的 prefill 拖尾。把长 prompt 请求路由到独立队列、复用其缓存的 prompt embedding 跨步使用，可削掉这部分尖刺。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-45\">四十五 · 监控面与回滚开关的最小集合</h3>\n<p>监控面按“组合正确性、显存、批形、时延”四条线组织，每条线一个可执行的回滚开关，而不是一堆只读仪表。组合正确性线：inf/nan 计数、<span class=\"formula\">$$\\max|\\hat{x}|$$</span> 分位数、槽位对齐校验（偶数槽必须是 uncond）——任一异常触发“组合切 FP32”开关。显存线：<span class=\"formula\">$$2B\\cdot a+R$$</span> 预估与实测水位、分配失败计数——触发“该档位降级串行”开关。批形线：填充率与批组成变动率——触发“下调批上限”开关。时延线：P99 批时延与回退率——触发“重档独立路由”开关。</p>\n<p>回滚必须可灰度：开关按 (分辨率档, <span class=\"formula\">$$s$$</span> 档, 量化档) 三元组粒度生效，先在单个副本上验证再全量。禁止全局一刀切回串行，那会把合并带来的吞吐收益全部丢掉。代价是开关状态本身要进配置管理，三元组组合爆炸时需要收敛到少数几个业务档位，这也是为什么 <span class=\"formula\">$$s$$</span> 必须在请求入口按业务分层预设——输出端合并无法中途按样本动态调 <span class=\"formula\">$$s$$</span>，灵活性下降是批合并的固有约束，监控与回滚只能在这个约束内做文章。</p>\n<p>具体例子：某档位 <span class=\"formula\">$$s$$</span> 下 inf 计数非零，灰度把该档位组合切 FP32，其余档位不动，吞吐损失局限在单档；若全量切 FP32，所有档位的组合带宽翻倍，得不偿失。这就是按三元组灰度的意义。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-46\">四十六 · 失败模式与相邻算法的边界</h3>\n<p>把失败模式对齐到算法选择上：精度污染指向“组合必须 FP32”的硬约束，与量化路径的耦合点是 GEMM 输出误差被 <span class=\"formula\">$$s$$</span> 放大；OOM 指向“峰值翻倍”的固有代价，与分块/offload 的配合是必选项而非优化项；批抖动与路由不均指向调度层，与 CFG 蒸馏的对比在此显形——蒸馏把 guidance 蒸进单分支，从根上消除 2B 拼接，也就消除了这三类失败模式，代价是训练成本与模型结构变更；批合并不改结构、无训练成本，但把失败模式全部推给运行时。</p>\n<p>工程判断因此落在“运行时是否具备确定性回退能力”上。若服务端没有按三元组灰度的回滚开关、没有准入层的 <span class=\"formula\">$$2B\\cdot a+R$$</span> 预估，批合并的吞吐收益会被尾延迟尖刺和 OOM 重试吃掉。反之，若回退路径确定、监控面收敛到四个开关，批合并就是低风险的高吞吐路径。这条判断与部署配方里的量化叠加直接相关：FP8/FP4 降低 <span class=\"formula\">$$a$$</span> 从而放宽 <span class=\"formula\">$$B$$</span> 上限，但也抬高组合点的精度风险，两者必须在同一张三元组表里联合标定，而不是分别调优。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-47\">四十七 · 失败模式与诊断：从精度溢出到批抖动的现场排查</h3>\n<p>批合并方案最隐蔽的失效不在吞吐，而在数值域。引导组合 $\\epsilon=\\epsilon_{\\mathrm{uncond}}+s(\\epsilon_{\\mathrm{cond}}-\\epsilon_{\\mathrm{uncond}})$ 中，当 $s$ 较大时，差值项 $(\\epsilon_{\\mathrm{cond}}-\\epsilon_{\\mathrm{uncond}})$ 被放大，动态范围随 $s$ 线性扩张；若组合在 FP16/BF16 下执行，大 $s$ 场景会出现溢出或饱和，表现为画面过曝、色块崩坏。工程上必须把切片后的组合强制提升到 FP32 计算再降回低精度写入 latent，并在监控里对 $|\\epsilon_{\\mathrm{cond}}-\\epsilon_{\\mathrm{uncond}}|$ 的滑动分位数设阈值——该值异常抬升往往先于画质投诉出现。concat 顺序同样是精度事故源：前半 uncond、后半 cond 的顺序一旦与切分索引错位，引导方向反转，输出语义偏离 prompt 且日志无报错，只能靠对同一 prompt 做 A/B 采样比对来定位，因此顺序与索引应作为常量在代码里单点定义，禁止在调度层重排。</p>\n<p>显存侧的核心代价是 concat 后 2B 张量使激活峰值翻倍。高分辨率、大 DiT 档位下，峰值一旦越过预算即触发 OOM，服务端 batch 被迫回退串行双前向，吞吐瞬间跌回基线，且回退是静默的——只有吞吐曲线出现台阶式下坠。诊断应把“峰值显存 / 预算”作为一等信息上报，配合分块或 offload 把峰值压回预算内；量化与批合并叠加时，2B 张量按同一权重计算，FP8/FP4 可缓解但无法抵消激活翻倍，因此 B 的上界必须由显存峰值反推而非按请求队列长度拍定。批抖动则来自请求形态混合：长 prompt 的文本编码虽只算一次并缓存，但首步 prefill 开销集中，短请求被长请求拖住形成队头阻塞；表现为 step 时延方差随队列长度上升。监控应分离“首步时延”与“稳态 step 时延”两条曲线，前者尖刺指向 embedding 缓存未命中，后者尖刺指向 2B 前向的 GEMM 尾块。</p>\n<p>路由不均与尾延迟尖刺在张量并行拓扑下更棘手：合并后的 2B 前向使单次 kernel 更重，任一 GPU 的显存碎片或时钟降频都会把整批拖入长尾，而 batch 内所有请求共享同一 step 节奏，一个慢分片即放大为全局尾延迟。可用的判据是每 step 的 all-reduce 等待占比，占比抬升说明并行域内负载已失衡。回滚策略应分级：一级回滚只把 $s$ 从业务分层预设中下调并切回 FP32 组合；二级回滚把 B 减半、保留合并路径；三级回滚整体退回串行双前向并清空 embedding 缓存，避免旧缓存与新路径的索引错配。由于 $s$ 固定在输出端合并、无法按样本动态调整，长尾请求与批量请求共用同一 $s$ 时画质与语义对齐难以兼顾，回滚判定应以业务分层的 SLO 违约率为触发条件，而非单请求画质。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要怀疑</th><th>观测信号</th><th>处置</th></tr></thead><tbody><tr><td>画面过曝/色块</td><td>低精度组合溢出</td><td>差值项分位数抬升</td><td>组合切 FP32，降 $s$</td></tr><tr><td>吞吐台阶下坠</td><td>2B 激活 OOM 回退</td><td>峰值显存/预算比</td><td>分块、offload、减 B</td></tr><tr><td>语义偏离 prompt</td><td>concat 顺序错位</td><td>A/B 采样比对</td><td>索引单点定义并回滚</td></tr><tr><td>尾延迟尖刺</td><td>并行域负载失衡</td><td>all-reduce 等待占比</td><td>重排拓扑、分级回滚</td></tr></tbody></table>\n<h3 id=\"alg-cfg-batch-merge-sec-48\">四十八 · 决策轴：把选择压缩成三个可测维度</h3>\n<p>与 CFG 批合并相邻的算法有四类：串行双前向（每步 cond、uncond 各跑一次）、批合并（2B 单次前向、输出端线性组合）、CFG 蒸馏（把 guidance 蒸进单分支，推理只跑一次 B）、以及条件缓存族（跨步复用文本 embedding 或跨请求复用 KV）。四者并非同一层面的替代品——条件缓存是批合并的前置优化，蒸馏是模型级替换。选型时不要按“哪个更快”排序，而应按三个可测维度切分：单步显存峰值是否落在预算内、guidance scale 是否需要按请求动态变化、以及文本编码开销在端到端时延中的占比。</p>\n<p>第一个维度决定批合并能否成立。concat 后的 2B 张量使激活显存翻倍，峰值近似为 <span class=\"formula\">$$M_{\\text{peak}}\\approx 2B\\cdot A_{\\text{act}}(H,W)+W_{\\text{weight}}$$</span>，其中 $A_{\\text{act}}$ 随分辨率平方增长。当 $M_{\\text{peak}}$ 超过单卡预算时，批合并必须与分块、offload 或量化叠加，否则回退串行。第二个维度是灵活性代价：批合并的 $s$ 在输出端合并，中途无法按样本改写，长尾请求与批量请求共用同一 $s$ 时画质与语义对齐难以兼顾；蒸馏同样把 $s$ 固化进权重，只有串行双前向保留逐样本调 $s$ 的能力。第三个维度是 prefill 占比：长 prompt 场景下 T5/CLIP 编码只算一次即可跨步复用，这部分收益与批合并正交，二者可叠加。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-49\">四十九 · 决策表：五种形态的适用条件对照</h3>\n<table class=\"mini\">\n<thead>\n<tr><th>形态</th><th>单步前向次数</th><th>显存峰值</th><th>逐样本调 s</th><th>训练成本</th><th>适用条件</th></tr>\n</thead>\n<tbody>\n<tr><td>串行双前向</td><td>2（各 B）</td><td>1×</td><td>支持</td><td>无</td><td>显存紧、s 需按请求分层、流量低</td></tr>\n<tr><td>批合并</td><td>1（2B）</td><td>≈2×</td><td>不支持</td><td>无</td><td>显存充裕、DiT 中等、在线高吞吐</td></tr>\n<tr><td>批合并 + 条件缓存</td><td>1（2B）</td><td>≈2×</td><td>不支持</td><td>无</td><td>长 prompt、多步采样、prefill 占比高</td></tr>\n<tr><td>CFG 蒸馏</td><td>1（B）</td><td>1×</td><td>不支持</td><td>需蒸馏训练</td><td>模型可改、显存与算力双紧、s 固定</td></tr>\n<tr><td>串行 + 条件缓存</td><td>2（各 B）</td><td>1×</td><td>支持</td><td>无</td><td>显存紧但 prompt 长、需保留 s 灵活性</td></tr>\n</tbody>\n</table>\n<p>表中“显存峰值”以串行双前向为基准归一。批合并与蒸馏都把单步前向次数压到 1，但路径不同：前者靠 batch 维拼接摊薄 kernel launch 与调度开销，GEMM 的 M 维更饱满，Tensor Core 利用率高于两次小 batch；后者靠改模型结构彻底消除第二分支，显存与算力同时减半，代价是蒸馏训练与 $s$ 固化。条件缓存不改变前向次数，只消除文本编码的重复计算，因此与其余四行均可组合，是唯一“正交”的选项。</p>\n<p>一个具体判断例子：在线文生图服务，DiT 规模中等、分辨率为基准档、显存预算允许 2B 激活，则批合并 + 条件缓存是默认解；若同一服务要承接高分辨率长尾请求，2B 峰值触发 OOM，则按请求分辨率分流——基准档走批合并，高分辨率档走串行 + 条件缓存，两档共用同一文本编码缓存，避免重复 prefill。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-50\">五十 · 吞吐判据：2B 与 B 的收益边界</h3>\n<p>批合并的吞吐收益来自大 batch 下 MMA 利用率提升，但并非无条件成立。设单次前向耗时为 $t_{\\text{fwd}}(n)$，则两种形态的吞吐对比为</p>\n<div class=\"formula\">$$\\text{Throughput}\\approx\\frac{2B}{t_{\\text{fwd}}(2B)}\\ \\text{vs}\\ \\frac{B}{t_{\\text{fwd}}(B)}$$</div>\n<p>批合并占优的条件是 $t_{\\text{fwd}}(2B)&lt;2\\,t_{\\text{fwd}}(B)$，即 2B 前向的耗时增长慢于 batch 翻倍——这正是大 batch 摊薄固定开销（kernel launch、调度、权重读取）的区间。当 2B 逼近显存上限、触发分块或 offload 时，$t_{\\text{fwd}}(2B)$ 的增长可能超过线性，批合并的吞吐优势被抵消，甚至因分块开销反超串行。工程上应把 2B 控制在显存峰值的舒适区，而非顶格拼批；实测吞吐提升 1.3–1.6 倍对应的是这一区间内的典型表现。</p>\n<p>另一个代价维度是功耗与带宽。批合并把两次权重读取合并为一次，HBM 带宽占用下降；但激活翻倍使片上流量上升，二者在带宽预算内相互抵消的程度取决于 DiT 的算术强度。对算术强度高的中等 DiT，权重读取是瓶颈，批合并收益明显；对高分辨率、激活主导的负载，带宽节省被激活流量吃掉，收益收窄。这也是决策表把“DiT 规模中等”列为批合并适用条件的原因。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-51\">五十一 · 稳定性对照：错位与溢出的不同暴露面</h3>\n<p>批合并的失败模式集中在两处：concat 顺序或切分索引与合并公式错位，导致 guidance 方向反转，输出过饱和或语义偏离 prompt，且难以从日志定位；以及 $s$ 较大时数值动态范围变大，低精度下易溢出。前者是结构性问题，后者是数值问题。对照之下，串行双前向没有 concat 顺序问题，但每步两次 kernel launch 使调度开销翻倍；蒸馏没有输出端合并，因而也无方向反转风险，但蒸馏偏差会以系统性画质损失的形式出现，且不可通过调 $s$ 补偿。</p>\n<p>数值稳定性上，批合并要求引导组合保持在 FP32：concat 后的 2B 张量按同一权重计算，量化可与 FP8/FP4 叠加，但输出端做 $\\epsilon_{\\text{uncond}}+s(\\epsilon_{\\text{cond}}-\\epsilon_{\\text{uncond}})$ 时，差值项在 $s$ 大时动态范围扩张，低精度累加会溢出。工程做法是把切片后的组合放到 FP32 完成，再写回单份 latent 进入 scheduler。串行双前向同样需要 FP32 组合，但两次前向各自独立，溢出只影响单路，定位更容易。这一差异意味着：批合并的数值调试成本高于串行，需在合并公式处加显式的范围检查。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-52\">五十二 · 组合与迁移：从单卡到并行拓扑的选择顺序</h3>\n<p>选型不是一次静态决策，而是随部署拓扑迁移的过程。单卡场景下，规模上限由单卡显存峰值决定：2B 拼得下则批合并，拼不下则串行 + 条件缓存。张量并行场景下，2B 张量按 TP 切分到多卡，单卡峰值回落，批合并重新可行，但 concat 与切分必须在同一 rank 布局下保持一致，否则切片索引跨 rank 错位，等价于方向反转。此时决策顺序应为：先确认 TP 切分后单卡 2B 峰值是否在预算内，再确认 concat 顺序在 rank 间是否统一，最后才比较吞吐。</p>\n<p>与蒸馏的迁移关系则是模型级的：批合并不改模型结构、无训练成本，可在现有权重上直接启用；蒸馏需要离线训练并把 $s$ 固化，一旦业务需要逐样本调 $s$ 就无法回退。因此工程判断的落点是：把批合并视为默认的推理侧优化，把蒸馏视为当显存与算力双紧且 $s$ 可固定时的模型级替换，二者不叠加——蒸馏后的单分支已无 uncond 路可拼，批合并失去对象。条件缓存则始终保留，无论走哪条路径，文本 embedding 跨步复用都是净收益。</p>\n<p>最后一个具体机制判断：请求入口按业务分层预设 $s$，是批合并下唯一可行的灵活性补偿。由于合并发生在输出端、中途无法按样本改写 $s$，长尾请求与批量请求共用同一 $s$ 时画质与语义对齐难以兼顾；把 $s$ 的分层前移到请求路由，用不同队列承载不同 $s$ 档位，可在不改合并公式的前提下恢复部分灵活性——代价是队列碎片化，batch 拼不满时 2B 的 M 维饱满度下降，吞吐收益收窄。这一权衡应纳入容量规划，而非留到运行时暴露。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-53\">五十三 · 边界判定：批合并、串行双前向与 CFG 蒸馏的取舍</h3>\n<p>把 CFG 批合并放进同族算法谱系，实际只有三条可选路径：串行双前向（每步 cond 一次、uncond 一次）、批合并（concat 成 2B 单次前向）、CFG 蒸馏（把 guidance 蒸进单分支，推理时只跑一次条件前向）。三者的差别不在数学结果——理想精度下都逼近 $\\hat{x}=x_{\\text{uncond}}+s\\,(x_{\\text{cond}}-x_{\\text{uncond}})$——而在系统代价落在哪一侧。串行双前向把代价压在调度与 GEMM 形状上：每步两次 kernel launch、两次小 batch GEMM，M 维偏窄，Tensor Core 利用率上不去，但显存峰值只对应 B。批合并把两次 launch 合成一次、把 M 维填到 2B，代价转移到激活显存峰值翻倍。蒸馏把代价前移到训练阶段，推理侧既无 2B 峰值也无二次 launch，但模型结构被改写、guidance scale 的可调范围被压缩，且需要额外的蒸馏训练投入。决策的第一刀就切在这里：显存预算能否容纳 2B 峰值，决定批合并是否在候选集内。</p>\n<p>用吞吐公式把三者的收益差量化。设单次前向耗时为 $t_{\\text{fwd}}(N)$，N 为 batch：串行双前向吞吐约 $\\frac{B}{t_{\\text{fwd}}(B)}$ 量级（两次 B 前向串行），批合并为 $\\frac{2B}{t_{\\text{fwd}}(2B)}$。收益全部来自 $t_{\\text{fwd}}(2B)&lt;2\\,t_{\\text{fwd}}(B)$ 这一不等式——大 batch 下 MMA 利用率更高、launch 与调度开销被摊薄，实测吞吐提升 1.3–1.6 倍即由此而来；若 DiT 在该形状下已进入带宽瓶颈或 occupancy 饱和，不等式收窄，收益随之衰减。蒸馏分支的吞吐上限是 $\\frac{B}{t_{\\text{fwd}}(B)}$ 但只跑一次条件前向，等效于把 2B 的活压成 B，理论吞吐高于批合并，代价是画质与 $s$ 可控性的让渡。三者的适用条件因此可以写成一张判定表：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>串行双前向</th><th>批合并</th><th>CFG 蒸馏</th></tr></thead><tbody><tr><td>显存峰值</td><td>1×（B 激活）</td><td>2×（2B 激活），高分辨率易 OOM</td><td>1×</td></tr><tr><td>kernel launch / 调度</td><td>每步 2 次</td><td>每步 1 次，开销减半</td><td>每步 1 次</td></tr><tr><td>GEMM M 维饱满度</td><td>低</td><td>高</td><td>中（单分支 B）</td></tr><tr><td>guidance scale 灵活性</td><td>可按样本调</td><td>输出端固定合并，无法中途按样本调 $s$</td><td>受蒸馏范围约束</td></tr><tr><td>训练成本</td><td>无</td><td>无</td><td>需蒸馏训练</td></tr><tr><td>典型适用</td><td>显存紧张、高分辨率大 DiT</td><td>显存充裕、中等 DiT、在线服务</td><td>追求极致单分支吞吐、$s$ 分布稳定</td></tr></tbody></table>\n<p>批合并的失效条件集中在两处。其一是显存：concat 后的 2B 张量使激活峰值翻倍，高分辨率、大 DiT 下若未配合分块或 offload 把峰值压回预算，直接触发 OOM，服务端 batch 被迫回退到串行双前向——此时收益归零而切换成本已付。其二是数值：guidance scale $s$ 大时组合式的动态范围被放大，低精度下 $\\epsilon_{\\text{cond}}-\\epsilon_{\\text{uncond}}$ 的差值项易溢出，组合必须保持在 FP32 完成，量化只能叠加在 2B 前向的权重与激活上，不能把合并也压进 FP8/FP4。还有一类静默失败：concat 顺序必须固定为前半 uncond、后半 cond，切分索引与合并公式一一对应；一旦错位，guidance 方向反转，输出过饱和或语义偏离 prompt，日志里看不出异常，只能靠固定模板与断言守住。工程判断因此很直接：显存峰值预算能覆盖 2B 且 $s$ 在请求入口按业务分层预设、无需逐样本动态调整时，批合并是默认选择；反之，高分辨率大 DiT 场景应保留串行双前向作为回退路径，或转向蒸馏分支以换取单分支吞吐。</p>\n\n<h3 id=\"alg-cfg-batch-merge-sec-54\">五十四 · 同族算法怎么选：批合并、串行双前向与 CFG 蒸馏的决策边界</h3>\n<p>批合并的适用条件由显存峰值而非算力决定。concat 后输入张量为 2B，DiT 每层激活与 attention 工作集同步翻倍，单卡预算必须容纳 2B 的峰值，否则在进入 scheduler 前就 OOM。决策时先算一笔显存账：设单样本在给定分辨率下的激活峰值为 $A$、权重与 KV/文本缓存为 $W$，则批合并要求 $W+2B\\cdot A\\le$ 可用显存，而串行双前向只需 $W+B\\cdot A$。这解释了为什么中等 DiT、显存充裕的在线文生图服务是它的主场，而高分辨率大 DiT 一旦 $A$ 抬升，2B 峰值立刻越界，服务端 batch 被迫回退到串行双前向——回退不是配置问题，是容量问题。</p>\n<p>三族算法的取舍可以压成一张表。串行双前向每步两次 kernel launch、两次小 batch GEMM，调度开销大但显存峰值最低，且天然允许逐样本调 $s$；批合并把两路拼成一次前向，GEMM 的 M 维饱满、Tensor Core 利用率高，吞吐提升 1.3–1.6 倍，代价是显存翻倍与 $s$ 在输出端固定；CFG 蒸馏把引导蒸进单分支，显存与算力都回到单前向水平，但需要训练成本且改动模型结构。选择顺序应是：先看显存能否容纳 2B，再看业务是否需要按样本动态调 $s$，最后才比较吞吐收益。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>显存峰值</th><th>调度开销</th><th>逐样本调 s</th><th>适用条件</th></tr></thead><tbody><tr><td>串行双前向</td><td>W+B·A</td><td>两次 launch</td><td>支持</td><td>显存紧、长尾 $s$ 分层</td></tr><tr><td>批合并</td><td>W+2B·A</td><td>一次 launch</td><td>不支持</td><td>显存充裕、中等 DiT、在线高吞吐</td></tr><tr><td>CFG 蒸馏</td><td>W+B·A</td><td>一次 launch</td><td>不支持</td><td>可接受训练、追求极致省算</td></tr></tbody></table>\n<p>失效条件集中在两处。其一，concat 顺序必须固定为前半 uncond、后半 cond，切分索引与 $\\epsilon=\\epsilon_{\\mathrm{uncond}}+s(\\epsilon_{\\mathrm{cond}}-\\epsilon_{\\mathrm{uncond}})$ 一一对应；顺序错位会让引导方向反转，输出过饱和或语义偏离 prompt，且日志里只看到正常吞吐，故障定位极难，工程上应把顺序与索引写成同一处常量并在启动时断言。其二，$s$ 固定在输出端合并，无法在中途按样本调整，长尾请求与批量请求共用同一 $s$ 时画质与语义对齐难以兼顾，需在请求入口按业务分层预设 $s$，把灵活性让渡给路由层而非模型层。低精度下 $s$ 大时动态范围膨胀，组合必须留在 FP32，否则 FP8/FP4 路径上易溢出。</p>\n<p>规模上限由单卡显存峰值与并行拓扑共同决定：张量并行能把 $W$ 摊薄，却摊不薄每卡的 2B 激活，因此批合并的 B 上限随 TP 增大反而更受激活约束；配合分块或 offload 可把峰值压回预算，但 offload 引入的显存往返会吃掉一部分合并省下的带宽收益。判断准则很直接：若 offload 流量超过合并减少的 kernel launch 与显存往返开销，批合并的净收益转负，此时应退回串行双前向或改用蒸馏分支。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2023 · 扩散服务化与 SLO 调度</td></tr><tr><td>解决什么</td><td>Classifier-Free Guidance 每步要跑条件与无条件两次前向，算力翻倍且两次前向的 KV/激活无法共…</td></tr><tr><td>一句话机制</td><td>把条件与无条件样本在 batch 维拼接成一次前向，文本编码与 KV 只算一次并缓存，输出按通道做引导组合，减少 ke…</td></tr><tr><td>代价与失效</td><td>batch 翻倍使激活显存翻倍，高分辨率下可能触发 OOM，需要与量化/分块配合；引导尺度 s 大时数值动态范围变大，低精度下易溢出，需保…</td></tr><tr><td>后继</td><td>DiT MX 混合精度分块</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-cfg-batch-merge · 共 8 个片段</p>\n";break;}}})();
